// 内置 lite 诗词数据集（来源：诗词游乐场 poems_classic_0.json，小学必背 75 首）
export const BUNDLED_POEMS = [{"id":"k0","title":"江南","author":"汉乐府","dynasty":"汉","paragraphs":["江南可采莲，莲叶何田田，鱼戏莲叶间。","鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。"],"content_text":"江南可采莲，莲叶何田田，鱼戏莲叶间。鱼戏莲叶东，鱼戏莲叶西，鱼戏莲叶南，鱼戏莲叶北。","pinyin":[["jiāng","nán","kě","cǎi","lián","，","lián","yè","hé","tián","tián","，","yú","xì","lián","yè","jiān","。"],["yú","xì","lián","yè","dōng","，","yú","xì","lián","yè","xī","，","yú","xì","lián","yè","nán","，","yú","xì","lián","yè","běi","。"]],"shiyi":"江南又到了适宜采莲的季节了，莲叶浮出水面，挨挨挤挤，重重叠叠，迎风招展。在茂密如盖的荷叶下面，欢快的鱼儿在不停的嬉戏玩耍。\n一会儿在这儿，一会儿又忽然游到了那儿，说不清究竟是在东边，还是在西边，还是在南边，还是在北边。\n\n","zhushi":"汉乐府：原是汉初采诗制乐的官署，后来又专指汉代的乐府诗。汉惠帝时，有乐府令一官，可能当时已设有乐府。武帝时乐府规模扩大，成为一个专设的官署，掌管郊祀、巡行、朝会、宴飨时的音乐，兼管采集民间歌谣，以供统治者观风察俗，了解民情厚薄。这些采集来的歌谣和其他经乐府配曲入乐的诗歌即被后人称为乐府诗。\n田田：荷叶茂盛的样子。\n可：在这里有“适宜” 、“ 正好”的意思。\n\n"},{"id":"k1","title":"长歌行","author":"汉乐府","dynasty":"汉","paragraphs":["青青园中葵，朝露待日晞。","阳春布德泽，万物生光辉。","常恐秋节至，焜黄华叶衰。","百川东到海，何时复西归？","少壮不努力，老大徒伤悲！"],"content_text":"青青园中葵，朝露待日晞。阳春布德泽，万物生光辉。常恐秋节至，焜黄华叶衰。百川东到海，何时复西归？少壮不努力，老大徒伤悲！","pinyin":[["qīng","qīng","yuán","zhōng","kuí","，","cháo","lù","dài","rì","xī","。"],["yáng","chūn","bù","dé","zé","，","wàn","wù","shēng","guāng","huī","。"],["cháng","kǒng","qiū","jié","zhì","，","kūn","huáng","huá","yè","shuāi","。"],["bǎi","chuān","dōng","dào","hǎi","，","hé","shí","fù","xī","guī","？"],["shǎo","zhuàng","bù","nǔ","lì","，","lǎo","dà","tú","shāng","bēi","！"]],"shiyi":"园中的葵菜都郁郁葱葱，晶莹的朝露阳光下飞升。\n春天把希望洒满了大地，万物都呈现出一派繁荣。\n常恐那肃杀的秋天来到，树叶儿黄落百草也凋零。\n百川奔腾着东流到大海，何时才能重新返回西境？\n少年人如果不及时努力，到老来只能是悔恨一生。\n\n","zhushi":"长歌行：汉乐府曲题。这首诗选自《乐府诗集》卷三十，属相和歌辞中的平调曲。\n葵：“葵”作为蔬菜名，指中国古代重要蔬菜之一。《诗经·豳风·七月》：“七月亨葵及菽。”李时珍《本草纲目》说“葵菜古人种为常食，今之种者颇鲜。有紫茎、白茎二种，以白茎为胜。大叶小花，花紫黄色，其最小者名鸭脚葵。其实大如指顶，皮薄而扁，实内子轻虚如榆荚仁。”此诗“青青园中葵”即指此。\n朝露：清晨的露水。晞：天亮，引申为阳光照耀。\n”阳春“句：阳是温和。阳春是露水和阳光都充足的时候，露水和阳光都是植物所需要的，都是大自然的恩惠，即所谓的”德泽“。 布：布施，给予。 德泽：恩惠。\n秋节：秋季。\n焜黄：形容草木凋落枯黄的样子。 华（huā）：同“花”。 衰：一说读“cuī”，因为古时候没有“shuāi”这个音；一说读shuāi，根据语文出版社出版的《古代汉语》，除了普通话的规范发音之外，任何其他的朗读法都是不可取的。\n百川：大河流。\n少壮：年轻力壮，指青少年时代。\n老大：指年老了，老年。徒：白白地。\n\n"},{"id":"k2","title":"敕勒歌","author":"北朝民歌","dynasty":"南北朝","paragraphs":["敕勒川，阴山下。天似穹庐，笼盖四野。","天苍苍，野茫茫。风吹草低见牛羊。"],"content_text":"敕勒川，阴山下。天似穹庐，笼盖四野。天苍苍，野茫茫。风吹草低见牛羊。","pinyin":[["chì","lè","chuān","，","yīn","shān","xià","。","tiān","sì","qióng","lú","，","lóng","gài","sì","yě","。"],["tiān","cāng","cāng","，","yě","máng","máng","。","fēng","chuī","cǎo","dī","jiàn","niú","yáng","。"]],"shiyi":"阴山脚下啊，有敕勒族生活的大平原。敕勒川的天空啊，它的四面与大地相连，看起来好像牧民们居住的毡帐一般。\n蓝天下的草原啊，都翻滚着绿色的波澜，那风吹到草低处，有一群群的牛羊时隐时现。\n\n译文二\n辽阔的敕勒平原，就在千里阴山下，天空仿佛圆顶帐篷，广阔无边，笼罩着四面的原野。\n天空蓝蓝的，原野辽阔无边。风儿吹过，牧草低伏，显露出原来隐没于草丛中的众多牛羊。\n\n","zhushi":"《敕勒歌》：敕勒（chì lè）：种族名，北齐时居住在朔州（今山西省北部）一带。\n敕勒川：川：平川、平原。敕勒族居住的地方，在现在的山西、内蒙一带。北魏时期把今河套平原至土默川一带称为敕勒川。\n阴山：在今内蒙古自治区北部。\n穹庐（qióng lú）：用毡布搭成的帐篷，即蒙古包。\n笼盖四野（yǎ）：笼盖，另有版本作“笼罩”（洪迈《容斋随笔》卷一和胡仔《苕溪渔隐丛话》后集卷三十一）；四野，草原的四面八方。\n天苍苍：苍苍：青色。苍，青，天苍苍，天蓝蓝的。\n茫茫：辽阔无边的样子。\n见（xiàn）：同“现”，显露。\n\n"},{"id":"k3","title":"咏鹅","author":"骆宾王","dynasty":"唐","paragraphs":["鹅，鹅，鹅，曲项向天歌。","白毛浮绿水，红掌拨清波。"],"content_text":"鹅，鹅，鹅，曲项向天歌。白毛浮绿水，红掌拨清波。","pinyin":[["é","，","é","，","é","，","qǔ","xiàng","xiàng","tiān","gē","。"],["bái","máo","fú","lǜ","shuǐ","，","hóng","zhǎng","bō","qīng","bō","。"]],"shiyi":"白天鹅啊白天鹅，脖颈弯弯，向天欢叫。\n洁白的羽毛，漂浮在碧绿水面；红红的脚掌，拨动着清清水波。\n\n","zhushi":"曲项：弯着脖子。歌：长鸣。\n拨：划动。\n\n"},{"id":"k4","title":"风","author":"李峤","dynasty":"唐","paragraphs":["解落三秋叶，能开二月花。","过江千尺浪，入竹万竿斜。"],"content_text":"解落三秋叶，能开二月花。过江千尺浪，入竹万竿斜。","pinyin":[["jiě","luò","sān","qiū","yè","，","néng","kāi","èr","yuè","huā","。"],["guò","jiāng","qiān","chǐ","làng","，","rù","zhú","wàn","gān","xié","。"]],"shiyi":"能吹落秋天金黄的树叶，能吹开春天美丽的鲜花。\n刮过江面能掀千尺巨浪，吹进竹林能使万竿倾斜。\n\n","zhushi":"解落：吹落，散落。解：解开，这里指吹。三秋：秋季。一说指农历九月。\n能：能够。二月：农历二月，指春季。\n过：经过。\n斜：倾斜。\n\n"},{"id":"k5","title":"咏柳","author":"贺知章","dynasty":"唐","paragraphs":["碧玉妆成一树高，万条垂下绿丝绦。","不知细叶谁裁出，二月春风似剪刀。"],"content_text":"碧玉妆成一树高，万条垂下绿丝绦。不知细叶谁裁出，二月春风似剪刀。","pinyin":[["bì","yù","zhuāng","chéng","yī","shù","gāo","，","wàn","tiáo","chuí","xià","lǜ","sī","tāo","。"],["bù","zhī","xì","yè","shuí","cái","chū","，","èr","yuè","chūn","fēng","sì","jiǎn","dāo","。"]],"shiyi":"高高的柳树长满了翠绿的新叶，轻柔的柳枝垂下来，就像万条轻轻飘动的绿色丝带。\n这细细的嫩叶是谁的巧手裁剪出来的呢？原来是那二月里温暖的春风，它就像一把灵巧的剪刀。\n\n","zhushi":"碧玉：碧绿色的玉。这里用以比喻春天嫩绿的柳叶。\n妆：装饰，打扮。\n一树：满树。一：满，全。在中国古典诗词和文章中，数量词在使用中并不一定表示确切的数量。下一句的“万”，就是表示很多的意思。\n绦（tāo）：用丝编成的绳带。这里指像丝带一样的柳条。\n裁：裁剪。\n似：如同，好像。\n\n"},{"id":"k6","title":"回乡偶书","author":"贺知章","dynasty":"唐","paragraphs":["少小离家老大回，乡音无改鬓毛衰。","儿童相见不相识，笑问客从何处来。"],"content_text":"少小离家老大回，乡音无改鬓毛衰。儿童相见不相识，笑问客从何处来。","pinyin":[["shǎo","xiǎo","lí","jiā","lǎo","dà","huí","，","xiāng","yīn","wú","gǎi","bìn","máo","shuāi","。"],["ér","tóng","xiāng","jiàn","bù","xiāng","shí","，","xiào","wèn","kè","cóng","hé","chù","lái","。"]],"shiyi":"我在年少时离开家乡，到了迟暮之年才回来。我的乡音虽未改变，但鬓角的毛发却已经疏落。儿童们看见我，没有一个认识的。他们笑着询问：这客人是从哪里来的呀？　\n\n","zhushi":"偶书：随便写的诗。偶：说明诗写作得很偶然，是随时有所见、有所感就写下来的。 \n少小离家：贺知章三十七岁中进士，在此以前就离开家乡。老大：年纪大了。贺知章回乡时已年逾八十。\n乡音：家乡的口音。无改：没什么变化。一作“难改”。鬓毛：额角边靠近耳朵的头发。一作“面毛”。衰（cui）：减少，疏落。鬓毛衰：指鬓毛减少，疏落。\n相见：即看见我；相：带有指代性的副词。不相识：即不认识我。\n笑问：一本作“却问”，一本作“借问”。\n\n"},{"id":"k7","title":"凉州词","author":"王之涣","dynasty":"唐","paragraphs":["黄河远上白云间，一片孤城万仞山。","羌笛何须怨杨柳，春风不度玉门关。"],"content_text":"黄河远上白云间，一片孤城万仞山。羌笛何须怨杨柳，春风不度玉门关。","pinyin":[["huáng","hé","yuǎn","shàng","bái","yún","jiān","，","yī","piàn","gū","chéng","wàn","rèn","shān","。"],["qiāng","dí","hé","xū","yuàn","yáng","liǔ","，","chūn","fēng","bù","dù","yù","mén","guān","。"]],"shiyi":"\n黄河好像从白云间奔流而来，玉门关孤独地耸峙在高山中。\n将士何须哀怨那柳树不发芽，春风根本吹不到玉门关外。\n\n译文二\n纵目望去，黄河渐行渐远，好像奔流在缭绕的白云中间，就在黄河上游的万仞高山之中，一座孤城玉门关耸峙在那里，显得孤峭冷寂。\n何必用羌笛吹起那哀怨的杨柳曲去埋怨春光迟迟不来呢，原来玉门关一带春风是吹不到的啊！\n\n","zhushi":"凉州词：又名《出塞》。为当时流行的一首曲子（《凉州词》）配的唱词。\n原题二首，此其一，郭茂倩《乐府诗集》卷七十九《近代曲词》载有《凉州歌》，并引《乐苑》云：“《凉州》，宫调曲，开元中西凉府都督郭知运进”。凉州，唐陇右道凉州治所在姑臧县（今甘肃省武威市凉州区）。\n远上；远远向西望去。“远”一作“直”。\n黄河远上：远望黄河的源头。\n孤城：指孤零零的戍边的城堡。\n仞：古代的长度单位，一仞相当于七尺或八尺(等于231cm或264cm,约等于2.3m或2.6m)。\n羌笛：古羌族主要分布在甘、青、川一带。羌笛是羌族乐器，属横吹式管乐。属于一种乐器。\n何须：何必。何须怨：何必埋怨。\n杨柳：杨树的柳条，又指的是《杨柳曲》。\n度：吹到过。不度：吹不到\n玉门关：汉武帝置，因西域输入玉石取道于此而得名。故址在今甘肃敦煌西北小方盘城,是古代通往西域的要道。六朝时关址东移至今安西双塔堡附近。\n\n\n"},{"id":"k8","title":"登鹳雀楼","author":"王之涣","dynasty":"唐","paragraphs":["白日依山尽，黄河入海流。","欲穷千里目，更上一层楼。"],"content_text":"白日依山尽，黄河入海流。欲穷千里目，更上一层楼。","pinyin":[["bái","rì","yī","shān","jìn","，","huáng","hé","rù","hǎi","liú","。"],["yù","qióng","qiān","lǐ","mù","，","gèng","shàng","yī","céng","lóu","。"]],"shiyi":"夕阳依傍着西山慢慢地沉没， 滔滔黄河朝着东海汹涌奔流。\n若想把千里的风光景物看够， 那就要登上更高的一层城楼。\n\n","zhushi":"鹳雀楼：旧址在山西永济县，楼高三层，前对中条山，下临黄河。传说常有鹳雀在此停留，故有此名。\n白日：太阳。\n依：依傍。\n尽：消失。 这句话是说太阳依傍山峦沉落。\n欲：想要得到某种东西或达到某种目的的愿望，但也有希望、想要的意思。\n穷：尽，使达到极点。\n千里目：眼界宽阔。\n更：替、换。（不是通常理解的“再”的意思）\n\n"},{"id":"k9","title":"春晓","author":"孟浩然","dynasty":"唐","paragraphs":["春眠不觉晓，处处闻啼鸟。","夜来风雨声，花落知多少。"],"content_text":"春眠不觉晓，处处闻啼鸟。夜来风雨声，花落知多少。","pinyin":[["chūn","mián","bù","jué","xiǎo","，","chù","chù","wén","tí","niǎo","。"],["yè","lái","fēng","yǔ","shēng","，","huā","luò","zhī","duō","shǎo","。"]],"shiyi":"春日里贪睡不知不觉天已破晓，搅乱我酣眠的是那啁啾的小鸟。\n昨天夜里风声雨声一直不断，那娇美的春花不知被吹落了多少？\n\n","zhushi":"晓：天刚亮的时候，春晓：春天的早晨。\n不觉晓：不知不觉天就亮了。\n啼鸟：鸟的啼叫声。\n知多少：不知有多少。\n\n"},{"id":"k10","title":"凉州词","author":"王翰","dynasty":"唐","paragraphs":["葡萄美酒夜光杯，欲饮琵琶马上催。","醉卧沙场君莫笑，古来征战几人回？"],"content_text":"葡萄美酒夜光杯，欲饮琵琶马上催。醉卧沙场君莫笑，古来征战几人回？","pinyin":[["pú","táo","měi","jiǔ","yè","guāng","bēi","，","yù","yǐn","pí","pá","mǎ","shàng","cuī","。"],["zuì","wò","shā","chǎng","jūn","mò","xiào","，","gǔ","lái","zhēng","zhàn","jǐ","rén","huí","？"]],"shiyi":"酒筵上甘醇的葡萄美酒盛满在精美的夜光杯之中，歌伎们弹奏起急促欢快的琵琶声助兴催饮，想到即将跨马奔赴沙场杀敌报国，战士们个个豪情满怀。\n今日一定要一醉方休，即使醉倒在战场上又何妨？此次出征为国效力，本来就打算马革裹尸，没有准备活着回来。\n\n","zhushi":"凉州词：唐乐府名，属《近代曲辞》，是《凉州曲》的唱词，盛唐时流行的一种曲调名。凉州词：王翰写有《凉州词》两首，慷慨悲壮，广为流传。而这首《凉州词》被明代王世贞推为唐代七绝的压卷之作。\n夜光杯：用白玉制成的酒杯，光可照明，这里指华贵而精美的酒杯。据《海内十洲记》所载，为周穆王时西胡所献之宝。\n欲：将要。\n琵琶：这里指作战时用来发出号角的声音时用的。\n催：催人出征；也有人解作鸣奏助兴。\n沙场：平坦空旷的沙地，古时多指战场。\n君：你。\n征战：打仗。\n\n"},{"id":"k11","title":"出塞","author":"王昌龄","dynasty":"唐","paragraphs":["秦时明月汉时关，万里长征人未还。","但使龙城飞将在，不教胡马度阴山。"],"content_text":"秦时明月汉时关，万里长征人未还。但使龙城飞将在，不教胡马度阴山。","pinyin":[["qín","shí","míng","yuè","hàn","shí","guān","，","wàn","lǐ","cháng","zhēng","rén","wèi","hái","。"],["dàn","shǐ","lóng","chéng","fēi","jiāng","zài","，","bù","jiào","hú","mǎ","dù","yīn","shān","。"]],"shiyi":"依旧是秦汉时期的明月和边关，守边御敌鏖战万里征人未回还。\n倘若龙城的飞将卫青如今还在，绝不许匈奴南下牧马度过阴山。\n\n","zhushi":"但使：只要。\n龙城飞将：《汉书·卫青霍去病传》载，元光六年（前129年），卫青为车骑将军，出上谷，至笼城，斩首虏数百。笼城，颜师古注曰：“笼”与“龙”同。龙城飞将指的是卫青奇袭龙城的事情。其中，有人认为龙城飞将中飞将指的是汉飞将军李广，龙城是唐代的卢龙城（卢龙城就是汉代的李广练兵之地，在今河北省喜峰口附近一带，为汉代右北平郡所在地），纵观李广一生主要的时间都在抗击匈奴，防止匈奴掠边，其中每次匈奴重点进攻的汉地天子几乎都是派遣李广为太守，所以这种说法也不无道理。\n不教：不叫，不让。教，让。\n胡马：指侵扰内地的外族骑兵。\n度：越过。在漫长的边防线上，战争一直没有停止过，去边防线打仗的战士也还没有回来。 要是攻袭龙城的大将军卫青和飞将军李广今天还依然健在，绝不会让敌人的军队翻过阴山。\n\n"},{"id":"k12","title":"芙蓉楼送辛渐","author":"王昌龄","dynasty":"唐","paragraphs":["寒雨连江夜入吴，平明送客楚山孤。","洛阳亲友如相问，一片冰心在玉壶。"],"content_text":"寒雨连江夜入吴，平明送客楚山孤。洛阳亲友如相问，一片冰心在玉壶。","pinyin":[["hán","yǔ","lián","jiāng","yè","rù","wú","，","píng","míng","sòng","kè","chǔ","shān","gū","。"],["luò","yáng","qīn","yǒu","rú","xiāng","wèn","，","yī","piàn","bīng","xīn","zài","yù","hú","。"]],"shiyi":"迷蒙的烟雨，连夜洒遍吴地江天；清晨送走你，孤对楚山离愁无限！\n朋友啊，洛阳亲友若是问起我来；就说我依然冰心玉壶，坚守信念！\n\n","zhushi":"芙蓉楼：原名西北楼，在润州（今江苏省镇江市）西北。登临可以俯瞰长江，遥望江北。丹阳在今江苏省西南部，东北滨长江，大运河斜贯，属镇江市。辛渐：诗人的一位朋友。\n寒雨：秋冬时节的冷雨。连江：雨水与江面连成一片，形容雨很大。吴：古代国名，这里泛指江苏南部、浙江北部一带。江苏镇江一带为三国时吴国所属。\n平明：天亮的时候。客：指作者的好友辛渐。楚山：楚地的山。这里的楚也指南京一带，因为古代吴、楚先后统治过这里，所以吴、楚可以通称。孤：独自，孤单一人。\n洛阳：现位于河南省西部、黄河南岸。\n冰心，比喻纯洁的心。玉壶，道教概念妙真道教义，专指自然无为虚无之心。\n\n"},{"id":"k13","title":"鹿柴","author":"王维","dynasty":"唐","paragraphs":["空山不见人，但闻人语响。","返景入深林，复照青苔上。"],"content_text":"空山不见人，但闻人语响。返景入深林，复照青苔上。","pinyin":[["kōng","shān","bù","jiàn","rén","，","dàn","wén","rén","yǔ","xiǎng","。"],["fǎn","jǐng","rù","shēn","lín","，","fù","zhào","qīng","tái","shàng","。"]],"shiyi":"幽静的山谷里看不见人，只能听到那说话的声音。\n落日的影晕映入了深林，又照在青苔上景色宜人。\n\n","zhushi":"鹿柴（zhài）：“柴”同“寨“，栅栏。此为地名。\n但：只。闻：听见。\n返景：夕阳返照的光。“景”古时同“影”。\n照：照耀(着)。\n\n"},{"id":"k14","title":"送元二使安西","author":"王维","dynasty":"唐","paragraphs":["渭城朝雨浥轻尘，客舍青青柳色新。(一作：客舍依依杨柳春)","劝君更尽一杯酒，西出阳关无故人。"],"content_text":"渭城朝雨浥轻尘，客舍青青柳色新。(一作：客舍依依杨柳春)劝君更尽一杯酒，西出阳关无故人。","pinyin":[["wèi","chéng","cháo","yǔ","yì","qīng","chén","，","kè","shè","qīng","qīng","liǔ","sè","xīn","。","(","yī","zuò","：","kè","shè","yī","yī","yáng","liǔ","chūn",")"],["quàn","jūn","gèng","jìn","yī","bēi","jiǔ","，","xī","chū","yáng","guān","wú","gù","rén","。"]],"shiyi":"清晨的微雨湿润了渭城地面的灰尘，馆驿青堂瓦舍柳树的枝叶翠嫩一新。\n真诚地奉劝我的朋友再干一杯美酒，向西出了阳关就难以遇到故旧亲人。\n\n","zhushi":"渭城曲：另题作《送元二使安西》，或名《阳关曲》或《阳关三叠》。\n渭城：在今陕西省西安市西北，即秦代咸阳古城。浥（yì）：润湿。\n客舍：旅馆。柳色：柳树象征离别。\n阳关：在今甘肃省敦煌西南，为自古赴西北边疆的要道。\n\n"},{"id":"k15","title":"九月九日忆山东兄弟","author":"王维","dynasty":"唐","paragraphs":["独在异乡为异客，每逢佳节倍思亲。","遥知兄弟登高处，遍插茱萸少一人。"],"content_text":"独在异乡为异客，每逢佳节倍思亲。遥知兄弟登高处，遍插茱萸少一人。","pinyin":[["dú","zài","yì","xiāng","wèi","yì","kè","，","měi","féng","jiā","jié","bèi","sī","qīn","。"],["yáo","zhī","xiōng","dì","dēng","gāo","chù","，","biàn","chā","zhū","yú","shǎo","yī","rén","。"]],"shiyi":"独自远离家乡无法与家人团聚，每到重阳佳节倍加思念远方的亲人。\n远远想到兄弟们身佩茱萸登上高处，也会因为少我一人而生遗憾之情。\n\n","zhushi":"九月九日：即重阳节。古以九为阳数，故曰重阳。忆：想念。山东：王维迁居于蒲县（今山西永济县），在函谷关与华山以东，所以称山东。\n异乡：他乡、外乡。 为异客：作他乡的客人。\n佳节：美好的节日。\n登高：古有重阳节登高的风俗。\n茱萸（zhūyú）：一种香草，即草决明。古时人们认为重阳节插戴茱萸可以避灾克邪。\n\n"},{"id":"k16","title":"静夜思","author":"李白","dynasty":"唐","paragraphs":["床前明月光，疑是地上霜。","举头望明月，低头思故乡。"],"content_text":"床前明月光，疑是地上霜。举头望明月，低头思故乡。","pinyin":[["chuáng","qián","míng","yuè","guāng","，","yí","shì","dì","shàng","shuāng","。"],["jǔ","tóu","wàng","míng","yuè","，","dī","tóu","sī","gù","xiāng","。"]],"shiyi":"明亮的月光洒在床前的窗户纸上，好像地上泛起了一层霜。\n我禁不住抬起头来，看那天窗外空中的一轮明月，不由得低头沉思，想起远方的家乡。\n\n韵译\n皎洁月光洒满床，恰似朦胧一片霜。\n仰首只见月一轮，低头教人倍思乡。\n\n","zhushi":"静夜思：静静的夜里，产生的思绪 。\n床：今传五种说法。\n一指井台。已经有学者撰文考证过。中国教育家协会理事程实将考证结果写成论文发表在刊物上，还和好友创作了《诗意图》。\n二指井栏。从考古发现来看，中国最早的水井是木结构水井。古代井栏有数米高，成方框形围住井口，防止人跌入井内，这方框形既像四堵墙，又像古代的床。因此古代井栏又叫银床，说明井和床有关系，其关系的发生则是由于两者在形状上的相似和功能上的类同。古代井栏专门有一个字来指称，即“韩”字。《说文》释“韩”为“井垣也”，即井墙之意。\n三“床”即“窗”的通假字。本诗中的‘床’字，是争论和异议的焦点。我们可以做一下基本推理。本诗的写作背景是在一个明月夜，很可能是月圆前后，作者由看到月光，再看到明月，又引起思乡之情。 \n既然作者抬头看到了明月，那么作者不可能身处室内，在室内随便一抬头，是看不到月亮的。因此我们断定，‘床’是室外的一件物什，至于具体是什么，很难考证。从意义上讲，‘床’可能与‘窗’通假，而且在窗户前面是可能看到月亮的。但是，参照宋代版本，‘举头望山月’，便可证实作者所言乃是室外的月亮。从时间上讲，宋代版本比明代版本在对作者原意的忠诚度上，更加可靠。 \n四取本义，即坐卧的器具，《诗经·小雅·斯干》有“载寐之牀”，《易·剥牀·王犊注》亦有“在下而安者也。”之说，讲得即是卧具。\n五马未都等认为，床应解释为胡床。胡床，亦称“交床”、“交椅”、“绳床”。古时一种可以折叠的轻便坐具，马扎功能类似小板凳，但人所坐的面非木板，而是可卷折的布或类似物，两边腿可合起来。现代人常为古代文献中或诗词中的“胡床”或“床”所误。至迟在唐时，“床”仍然是“胡床”（即马扎，一种坐具）。\n疑：好像。 \n举头：抬头。\n\n"},{"id":"k17","title":"古朗月行","author":"李白","dynasty":"唐","paragraphs":["小时不识月，呼作白玉盘。","又疑瑶台镜，飞在青云端。(青云 一作：白云)","仙人垂两足，桂树何团团。","白兔捣药成，问言与谁餐？","蟾蜍蚀圆影，大明夜已残。","羿昔落九乌，天人清且安。","阴精此沦惑，去去不足观。","忧来其如何？凄怆摧心肝。"],"content_text":"小时不识月，呼作白玉盘。又疑瑶台镜，飞在青云端。(青云 一作：白云)仙人垂两足，桂树何团团。白兔捣药成，问言与谁餐？蟾蜍蚀圆影，大明夜已残。羿昔落九乌，天人清且安。阴精此沦惑，去去不足观。忧来其如何？凄怆摧心肝。","pinyin":[["xiǎo","shí","bù","shí","yuè","，","hū","zuò","bái","yù","pán","。"],["yòu","yí","yáo","tái","jìng","，","fēi","zài","qīng","yún","duān","。","(","qīng","yún"," ","yī","zuò","：","bái","yún",")"],["xiān","rén","chuí","liǎng","zú","，","guì","shù","hé","tuán","tuán","。"],["bái","tù","dǎo","yào","chéng","，","wèn","yán","yǔ","shuí","cān","？"],["chán","chú","shí","yuán","yǐng","，","dà","míng","yè","yǐ","cán","。"],["yì","xī","luò","jiǔ","wū","，","tiān","rén","qīng","qiě","ān","。"],["yīn","jīng","cǐ","lún","huò","，","qù","qù","bù","zú","guān","。"],["yōu","lái","qí","rú","hé","？","qī","chuàng","cuī","xīn","gān","。"]],"shiyi":"小时候不认识月亮， 把它称为白玉盘。\n又怀疑是瑶台仙镜，飞在夜空青云之上。\n月中的仙人是垂着双脚吗？月中的桂树为什么长得圆圆的？\n白兔捣成的仙药，到底是给谁吃的呢？\n蟾蜍把圆月啃食得残缺不全，皎洁的月儿因此晦暗不明。\n后羿射下了九个太阳，天上人间免却灾难清明安宁。\n月亮已经沦没而迷惑不清，没有什么可看的不如远远走开吧。\n心怀忧虑啊又何忍一走了之，凄惨悲伤让我肝肠寸断。\n\n韵译\n小时不识天上明月，把它称为白玉圆盘。怀疑它是瑶台仙镜，飞在夜空青云上边。\n月中仙人垂下双脚？月中桂树多么圆圆！白兔捣成不老仙药，借问一声给谁用餐？\n蟾蜍食月残缺不全，皎洁月儿因此晦暗。后羿射落九个太阳，天上人间清明平安。\n月亮沦没迷惑不清，不值观看想要离开。心怀忧虑不忍远去，凄惨悲伤肝肠寸断。\n\n","zhushi":"呼作：称为。\n白玉盘：指晶莹剔透的白盘子。\n疑：怀疑。\n瑶台：传说中神仙居住的地方。出处：《穆天子传》卷三：“天子宾于西王母，天子觞西王母于瑶池之上。西王母为天子谣曰：‘白云在天，山陵自出。道里悠远，山川间之。将子无死，尚能复来。’天子答之曰：‘予归东土，和治诸夏。万民平均，吾顾见汝。比及三年，将复而野。’”《武帝内传》称王母为“玄都阿母”。\n仙人垂两足：意思是月亮里有仙人和桂树。当月亮初生的时候，先看见仙人的两只脚，月亮渐渐圆起来，就看见仙人和桂树的全形。仙人，传说驾月的车夫，叫舒望，又名纤阿。\n团团：圆圆的样子。\n白兔捣药成，问言与谁餐：白兔老是忙着捣药，究竟是给谁吃呢？言外有批评长生不老药之意。问言，问。言，语助词，无实意。与谁，一作“谁与”\n蟾蜍：《五经通义》：“月中有兔与蟾蜍。”蟾蜍，传说月中有三条腿的蟾蜍，因此古诗文常以“蟾蜍”指代月亮。但本诗中蟾蜍则另有所指。\n圆影：指月亮。\n羿：我国古代神话中射落九个太阳的英雄。《淮南子·本经训》记载：尧时十日并出，草木皆枯。尧命羿仰射十日，中其九。下面的“乌”即日，《五经通义》：“日中有三足乌。”所以日又叫阳乌。\n天人：天上人间。\n阴精：《史记·天官书》：“月者，天地之阴，金之精也。”阴精也指月。\n沦惑：沉沦迷惑。\n去去：远去，越去越远。\n凄怆：悲愁伤感。\n\n"},{"id":"k18","title":"望庐山瀑布","author":"李白","dynasty":"唐","paragraphs":["日照香炉生紫烟，遥看瀑布挂前川。","飞流直下三千尺，疑是银河落九天。"],"content_text":"日照香炉生紫烟，遥看瀑布挂前川。飞流直下三千尺，疑是银河落九天。","pinyin":[["rì","zhào","xiāng","lú","shēng","zǐ","yān","，","yáo","kàn","pù","bù","guà","qián","chuān","。"],["fēi","liú","zhí","xià","sān","qiān","chǐ","，","yí","shì","yín","hé","luò","jiǔ","tiān","。"]],"shiyi":"香炉峰在阳光的照射下生起紫色烟霞，远远望见瀑布似白色绢绸悬挂在山前。\n高崖上飞腾直落的瀑布好像有几千尺，让人恍惚以为银河从天上泻落到人间。\n\n","zhushi":"香炉：指香炉峰。紫烟：指日光透过云雾，远望如紫色的烟云。\n遥看：从远处看。挂：悬挂。前川：一作“长川”。川：河流，这里指瀑布。\n直：笔直。三千尺：形容山高。这里是夸张的说法，不是实指。\n疑：怀疑。银河：古人指银河系构成的带状星群。九天：一作“半天”。\n\n"},{"id":"k19","title":"赠汪伦","author":"李白","dynasty":"唐","paragraphs":["李白乘舟将欲行，忽闻岸上踏歌声。","桃花潭水深千尺，不及汪伦送我情。"],"content_text":"李白乘舟将欲行，忽闻岸上踏歌声。桃花潭水深千尺，不及汪伦送我情。","pinyin":[["lǐ","bái","chéng","zhōu","jiāng","yù","xíng","，","hū","wén","àn","shàng","tà","gē","shēng","。"],["táo","huā","tán","shuǐ","shēn","qiān","chǐ","，","bù","jí","wāng","lún","sòng","wǒ","qíng","。"]],"shiyi":"李白坐上小船刚刚要离开，忽然听到岸上传来告别的歌声。\n即使桃花潭水有一千尺那么深，也不及汪伦送别我的一片情深。\n\n","zhushi":"踏歌：民间的一种唱歌形式，一边唱歌，一边用脚踏地打拍子，可以边走边唱。\n桃花潭：在今安徽泾县西南一百里。《一统志》谓其深不可测。\n深千尺：诗人用潭水深千尺比喻汪伦与他的友情，运用了夸张的手法（潭深千尺不是实有其事）写深情厚谊，十分动人。\n不及：不如。\n汪伦：李白的朋友。李白游泾（jīng）县（在今安徽省）桃花潭时，附近贾村的汪伦经常用自己酿的美酒款待李白，两人便由此结下深厚的友谊。历代出版的《李白集》、《唐诗三百首》、《全唐诗》注解，都认定汪伦是李白游历泾县时遇到的一个普通村民，这个观点一直延续至今，今人安徽学者汪光泽和李子龙先后研读了泾县《汪氏宗谱》、《汪渐公谱》、《汪氏续修支谱》，确知“汪伦又名凤林，为唐时知名士”，与李白、王维等人关系很好，经常以诗文往来赠答。开元天宝年间，汪伦为泾县令，李白“往候之，款洽不忍别”（详见《李白学刊》第二辑李子龙《关于汪伦其人》）。按此诗或为汪伦已闲居桃花潭时，李白来访所作。李白于公元754年（天宝十三载）自广陵、金陵至宣城，则此诗当不早于此前。\n\n"},{"id":"k20","title":"黄鹤楼送孟浩然之广陵","author":"李白","dynasty":"唐","paragraphs":["故人西辞黄鹤楼，烟花三月下扬州。","孤帆远影碧空尽，唯见长江天际流。 (唯 通：惟)"],"content_text":"故人西辞黄鹤楼，烟花三月下扬州。孤帆远影碧空尽，唯见长江天际流。 (唯 通：惟)","pinyin":[["gù","rén","xī","cí","huáng","hè","lóu","，","yān","huā","sān","yuè","xià","yáng","zhōu","。"],["gū","fān","yuǎn","yǐng","bì","kōng","jìn","，","wéi","jiàn","cháng","jiāng","tiān","jì","liú","。"," ","(","wéi"," ","tōng","：","wéi",")"]],"shiyi":"老朋友向我频频挥手，告别了黄鹤楼，在这柳絮如烟、繁花似锦的阳春三月去扬州远游。\n友人的孤船帆影渐渐地远去，消失在碧空的尽头，只看见一线长江，向邈远的天际奔流。\n\n","zhushi":"黄鹤楼：中国著名的名胜古迹，故址在今湖北武汉市武昌蛇山的黄鹄矶上，属于长江下游地带，传说三国时期的费祎于此登仙乘黄鹤而去，故称黄鹤楼。原楼已毁，现存楼为1985年修葺。孟浩然：李白的朋友。之：往、到达。广陵：即扬州。\n故人：老朋友，这里指孟浩然。其年龄比李白大，在诗坛上享有盛名。李白对他很敬佩，彼此感情深厚，因此称之为“故人”。辞：辞别。\n烟花：形容柳絮如烟、鲜花似锦的春天景物，指艳丽的春景。下：顺流向下而行。\n碧空尽：消失在碧蓝的天际。尽：尽头，消失了。碧空：一作“碧山”。\n唯见：只看见。天际流：流向天边 天际：天边，天边的尽头。\n\n"},{"id":"k21","title":"早发白帝城","author":"李白","dynasty":"唐","paragraphs":["朝辞白帝彩云间，千里江陵一日还。","两岸猿声啼不住，轻舟已过万重山。"],"content_text":"朝辞白帝彩云间，千里江陵一日还。两岸猿声啼不住，轻舟已过万重山。","pinyin":[["cháo","cí","bái","dì","cǎi","yún","jiān","，","qiān","lǐ","jiāng","líng","yī","rì","hái","。"],["liǎng","àn","yuán","shēng","tí","bù","zhù","，","qīng","zhōu","yǐ","guò","wàn","zhòng","shān","。"]],"shiyi":"清晨，朝霞满天，我就要踏上归程。从江上往高处看，可以看见白帝城彩云缭绕，如在云间，景色绚丽！千里之遥的江陵，一天之间就已经到达。\n两岸猿猴的啼声不断，回荡不绝。猿猴的啼声还回荡在耳边时，轻快的小船已驶过连绵不绝的万重山峦。\n\n译文二\n清晨，我告别高入云霄的白帝城江陵远在千里，船行只一日时间。\n两岸猿声，还在耳边不停地啼叫不知不觉，轻舟已穿过万重青山。\n\n","zhushi":"发：启程。白帝城：故址在今重庆市奉节县白帝山上。杨齐贤注：“白帝城，公孙述所筑。初，公孙述至鱼复，有白龙出井中，自以承汉土运，故称白帝，改鱼复为白帝城。”王琦注：“白帝城，在夔州奉节县，与巫山相近。所谓彩云，正指巫山之云也。”\n朝：早晨。辞：告别。彩云间：因白帝城在白帝山上，地势高耸，从山下江中仰望，仿佛耸入云间。\n江陵：今湖北荆州市。从白帝城到江陵约一千二百里，其间包括七百里三峡。郦道元《三峡》：“自三峡七百里中，两岸连山，略无阙处。重岩叠障，隐天蔽日，自非亭午时分，不见曦月。至于夏水襄陵，沿溯（或泝）阻绝。或王命急宣，有时朝发白帝，暮到江陵，其间千二百时里，虽乘奔御风，不以疾也。春冬之时，则素湍绿潭，回清倒影。绝巘（或巚）多生怪柏，悬泉瀑布，飞漱其间。清荣峻茂，良多趣味。每至晴初霜旦，林寒涧肃，常有高猿长啸，属引凄异。空谷传响，哀啭久绝。故渔者歌曰：‘巴东三峡巫峡长，猿鸣三声泪沾裳。’”还：归；返回。\n猿：猿猴。啼：鸣、叫。住：停息。\n万重山：层层叠叠的山，形容有许多。 \n\n"},{"id":"k22","title":"望天门山","author":"李白","dynasty":"唐","paragraphs":["天门中断楚江开，碧水东流至此回。","两岸青山相对出，孤帆一片日边来。"],"content_text":"天门中断楚江开，碧水东流至此回。两岸青山相对出，孤帆一片日边来。","pinyin":[["tiān","mén","zhōng","duàn","chǔ","jiāng","kāi","，","bì","shuǐ","dōng","liú","zhì","cǐ","huí","。"],["liǎng","àn","qīng","shān","xiāng","duì","chū","，","gū","fān","yī","piàn","rì","biān","lái","。"]],"shiyi":"长江犹如巨斧劈开天门雄峰，碧绿江水东流到此回旋澎湃。\n两岸青山对峙美景难分高下，遇见一叶孤舟悠悠来自天边。\n\n","zhushi":"天门山：位于安徽省和县与芜湖市长江两岸，在江北的叫西梁山，在江南的叫东梁山（古代又称博望山）。两山隔江对峙，形同天设的门户，天门由此得名。\n中断：江水从中间隔断两山。楚江：即长江。因为古代长江中游地带属楚国，所以叫楚江。开：劈开，断开。\n至此：意为东流的江水在这转向北流。一作“直北”。回：回漩，回转。指这一段江水由于地势险峻方向有所改变，并更加汹涌。\n两岸青山：分别指东梁山和西梁山。出：突出，出现。\n日边来：指孤舟从天水相接处的远方驶来，远远望去，仿佛来自日边。\n\n"},{"id":"k23","title":"别董大","author":"高适","dynasty":"唐","paragraphs":["千里黄云白日曛，北风吹雁雪纷纷。","莫愁前路无知己，天下谁人不识君。"],"content_text":"千里黄云白日曛，北风吹雁雪纷纷。莫愁前路无知己，天下谁人不识君。","pinyin":[["qiān","lǐ","huáng","yún","bái","rì","xūn","，","běi","fēng","chuī","yàn","xuě","fēn","fēn","。"],["mò","chóu","qián","lù","wú","zhī","jǐ","，","tiān","xià","shuí","rén","bù","shí","jūn","。"]],"shiyi":"千里黄云蔽天日色暗昏昏，北风吹着归雁大雪纷纷。\n不要担心前路茫茫没有知己，普天之下哪个不识君？\n\n就像鸟儿六翮飘摇自伤自怜，离开京洛已经十多年。\n大丈夫贫贱谁又心甘情愿，今天相逢可掏不出酒钱。\n\n","zhushi":"董大：指董庭兰，是当时有名的音乐家　。在其兄弟中排名第一，故称“董大”。\n黄云：天上的乌云，在阳光下，乌云是暗黄色，所以叫黄云。曛 ：昏暗。白日曛，即太阳黯淡无光。\n谁人：哪个人。君：你，这里指董大。\n翮（hé）：鸟的羽翼。飘飖（yáo）：飘动。六翮飘飖，比喻四处奔波而无结果。\n京洛：长安和洛阳。\n\n"},{"id":"k24","title":"绝句","author":"杜甫","dynasty":"唐","paragraphs":["两个黄鹂鸣翠柳，一行白鹭上青天。","窗含西岭千秋雪，门泊东吴万里船。"],"content_text":"两个黄鹂鸣翠柳，一行白鹭上青天。窗含西岭千秋雪，门泊东吴万里船。","pinyin":[["liǎng","gè","huáng","lí","míng","cuì","liǔ","，","yī","xíng","bái","lù","shàng","qīng","tiān","。"],["chuāng","hán","xī","lǐng","qiān","qiū","xuě","，","mén","bó","dōng","wú","wàn","lǐ","chuán","。"]],"shiyi":"两只黄鹂在翠绿的柳树间婉转地歌唱，一队整齐的白鹭直冲向蔚蓝的天空。\n我坐在窗前，可以望见西岭上堆积着终年不化的积雪，门前停泊着自万里外的东吴远行而来的船只。\n\n","zhushi":"西岭：西岭雪山。\n千秋雪：指西岭雪山上千年不化的积雪。\n泊：停泊。\n东吴：古时候吴国的领地，江苏省一带。\n万里船：不远万里开来的船只。\n\n"},{"id":"k25","title":"春夜喜雨","author":"杜甫","dynasty":"唐","paragraphs":["好雨知时节，当春乃发生。","随风潜入夜，润物细无声。","野径云俱黑，江船火独明。","晓看红湿处，花重锦官城。"],"content_text":"好雨知时节，当春乃发生。随风潜入夜，润物细无声。野径云俱黑，江船火独明。晓看红湿处，花重锦官城。","pinyin":[["hǎo","yǔ","zhī","shí","jié","，","dāng","chūn","nǎi","fā","shēng","。"],["suí","fēng","qián","rù","yè","，","rùn","wù","xì","wú","shēng","。"],["yě","jìng","yún","jù","hēi","，","jiāng","chuán","huǒ","dú","míng","。"],["xiǎo","kàn","hóng","shī","chù","，","huā","zhòng","jǐn","guān","chéng","。"]],"shiyi":"好雨似乎会挑选时辰，降临在万物萌生之春。\n伴随和风，悄悄进入夜幕。细细密密，滋润大地万物。\n浓浓乌云，笼罩田野小路，点点灯火，闪烁江上渔船。\n明早再看带露的鲜花，成都满城必将繁花盛开。\n\n","zhushi":"知：明白，知道。说雨知时节，是一种拟人化的写法。\n乃：就。发生：萌发生长。\n发生：萌发生长。\n潜（qián）：暗暗地，悄悄地。这里指春雨在夜里悄悄地随风而至。\n润物：使植物受到雨水的滋养。\n野径：田野间的小路。\n晓：天刚亮的时候。红湿处：雨水湿润的花丛。\n红湿处：指有带雨水的红花的地方。\n花重：花沾上雨水而变得沉重。\n重：读作zhòng（重在这里的意思是：沉重。所以读作第四声。）\n锦官城：成都的别称。\n\n"},{"id":"k26","title":"绝句","author":"杜甫","dynasty":"唐","paragraphs":["迟日江山丽，春风花草香。","泥融飞燕子，沙暖睡鸳鸯。"],"content_text":"迟日江山丽，春风花草香。泥融飞燕子，沙暖睡鸳鸯。","pinyin":[["chí","rì","jiāng","shān","lì","，","chūn","fēng","huā","cǎo","xiāng","。"],["ní","róng","fēi","yàn","zǐ","，","shā","nuǎn","shuì","yuān","yāng","。"]],"shiyi":"江山沐浴着春光，多么秀丽，春风送来花草的芳香。\n燕子衔着湿泥忙筑巢，暖和的沙子上睡着成双成对的鸳鸯。\n\n","zhushi":"迟日：春天日渐长，所以说迟日。 \n泥融：这里指泥土滋润、湿润。\n鸳鸯：一种水鸟，雄鸟与雌鸟常常双双出没。\n\n"},{"id":"k27","title":"江畔独步寻花","author":"杜甫","dynasty":"唐","paragraphs":["黄四娘家花满蹊，千朵万朵压枝低。","留连戏蝶时时舞，自在娇莺恰恰啼。"],"content_text":"黄四娘家花满蹊，千朵万朵压枝低。留连戏蝶时时舞，自在娇莺恰恰啼。","pinyin":[["huáng","sì","niáng","jiā","huā","mǎn","qī","，","qiān","duǒ","wàn","duǒ","yā","zhī","dī","。"],["liú","lián","xì","dié","shí","shí","wǔ","，","zì","zài","jiāo","yīng","qià","qià","tí","。"]],"shiyi":"黄四娘家花儿茂盛把小路遮蔽，万千花朵压弯枝条离地低又低。\n眷恋芬芳花间彩蝶时时在飞舞，自由自在娇软黄莺恰恰欢声啼。\n\n","zhushi":"黄四娘：杜甫住成都草堂时的邻居。蹊（xī）：小路。\n留连：即留恋，舍不得离去。\n娇：可爱的样子。恰恰：象声词，形容鸟叫声音和谐动听。一说“恰恰”为唐时方言，恰好之意。\n\n"},{"id":"k28","title":"枫桥夜泊","author":"张继","dynasty":"唐","paragraphs":["月落乌啼霜满天，江枫渔火对愁眠。","姑苏城外寒山寺，夜半钟声到客船。"],"content_text":"月落乌啼霜满天，江枫渔火对愁眠。姑苏城外寒山寺，夜半钟声到客船。","pinyin":[["yuè","luò","wū","tí","shuāng","mǎn","tiān","，","jiāng","fēng","yú","huǒ","duì","chóu","mián","。"],["gū","sū","chéng","wài","hán","shān","sì","，","yè","bàn","zhōng","shēng","dào","kè","chuán","。"]],"shiyi":"月亮已落下乌鸦啼叫寒气满天， 对着江边枫树和渔火忧愁而眠。\n姑苏城外那寂寞清静寒山古寺， 半夜里敲钟的声音传到了客船。\n\n","zhushi":"枫桥：在今苏州市阊门外。\n夜泊：夜间把船停靠在岸边。\n乌啼：一说为乌鸦啼鸣，一说为乌啼镇。\n霜满天：霜，不可能满天，这个“霜”字应当体会作严寒；霜满天，是空气极冷的形象语。\n江枫：一般解释作“江边枫树”，江指吴淞江，源自太湖，流经上海，汇入长江，俗称苏州河。另外有人认为指“江村桥”和“枫桥”。“枫桥”在吴县南门（阊阖门）外西郊，本名“封桥”，因张继此诗而改为“枫桥”。\n渔火：通常解释，“鱼火”就是渔船上的灯火；也有说法指“渔火”实际上就是一同打渔的伙伴。\n对愁眠：伴愁眠之意，此句把江枫和渔火二词拟人化。就是后世有不解诗的人，怀疑江枫渔火怎么能对愁眠，于是附会出一种讲法，说愁眠是寒山寺对面的山名。\n姑苏：苏州的别称，因城西南有姑苏山而得名。\n寒山寺：在枫桥附近，始建于南朝梁代。相传因唐代僧人寒山、拾得曾住此而得名。在今苏州市西枫桥镇。本名“妙利普明塔院”，又名枫桥寺；另一种说法，“寒山”乃泛指肃寒之山，非寺名。寺曾经数次重建，现在的寺宇，为太平天国以后新建。寺钟在第二次世界大战时，被日本人运走，下落不明。\n夜半钟声：当今的佛寺（春节）半夜敲钟，但当时有半夜敲钟的习惯，也叫「无常钟」或「分夜钟」。宋朝大文豪欧阳修曾提出疑问表示：“诗人为了贪求好句，以至于道理说不通，这是作文章的毛病，如张继诗句“夜半钟声到客船”，句子虽好，但那有三更半夜打钟的道理？”可是经过许多人的实地查访，才知苏州和邻近地区的佛寺，有打半夜钟的风俗。\n\n"},{"id":"k29","title":"滁州西涧","author":"韦应物","dynasty":"唐","paragraphs":["独怜幽草涧边生，上有黄鹂深树鸣。","春潮带雨晚来急，野渡无人舟自横。"],"content_text":"独怜幽草涧边生，上有黄鹂深树鸣。春潮带雨晚来急，野渡无人舟自横。","pinyin":[["dú","lián","yōu","cǎo","jiàn","biān","shēng","，","shàng","yǒu","huáng","lí","shēn","shù","míng","。"],["chūn","cháo","dài","yǔ","wǎn","lái","jí","，","yě","dù","wú","rén","zhōu","zì","héng","。"]],"shiyi":"最是喜爱涧边生长的幽幽野草，还有那树丛深处婉转啼唱的黄鹂。\n春潮不断上涨，还夹带着密密细雨。荒野渡口无人，只有一只小船悠闲地横在水面。\n\n","zhushi":"⑴滁州：在今安徽滁州以西。西涧：在滁州城西，俗名称上马河。　\n⑵独怜：唯独喜欢。幽草：幽谷里的小草。幽，一作“芳”。生：一作“行”。\n⑶深树：枝叶茂密的树。深，《才调集》作“远”。树，《全唐诗》注“有本作‘处’”。\n⑷春潮：春天的潮汐。\n⑸野渡：郊野的渡口。横：指随意飘浮。\n\n"},{"id":"k30","title":"游子吟","author":"孟郊","dynasty":"唐","paragraphs":["慈母手中线，游子身上衣。","临行密密缝，意恐迟迟归。","谁言寸草心，报得三春晖。"],"content_text":"慈母手中线，游子身上衣。临行密密缝，意恐迟迟归。谁言寸草心，报得三春晖。","pinyin":[["cí","mǔ","shǒu","zhōng","xiàn","，","yóu","zǐ","shēn","shàng","yī","。"],["lín","xíng","mì","mì","fèng","，","yì","kǒng","chí","chí","guī","。"],["shuí","yán","cùn","cǎo","xīn","，","bào","dé","sān","chūn","huī","。"]],"shiyi":"慈母用手中的针线，为远行的儿子赶制身上的衣衫。\n临行前一针针密密地缝缀，怕的是儿子回来得晚衣服破损。\n有谁敢说，子女像小草那样微弱的孝心，能够报答得了像春晖普泽的慈母恩情呢？\n\n","zhushi":"游子：古代称远游旅居的人。吟：诗体名称。\n游子：指诗人自己，以及各个离乡的游子。\n临：将要。\n意恐：担心。归：回来，回家。\n谁言：一作“难将”。言：说。寸草：小草。这里比喻子女。心：语义双关，既指草木的茎干，也指子女的心意。\n报得：报答。三春晖：春天灿烂的阳光，指慈母之恩。三春：旧称农历正月为孟春，二月为仲春，三月为季春，合称三春。晖：阳光。形容母爱如春天温暖、和煦的阳光照耀着子女。\n\n"},{"id":"k31","title":"早春呈水部张十八员外","author":"韩愈","dynasty":"唐","paragraphs":["天街小雨润如酥，草色遥看近却无。","最是一年春好处，绝胜烟柳满皇都。"],"content_text":"天街小雨润如酥，草色遥看近却无。最是一年春好处，绝胜烟柳满皇都。","pinyin":[["tiān","jiē","xiǎo","yǔ","rùn","rú","sū","，","cǎo","sè","yáo","kàn","jìn","què","wú","。"],["zuì","shì","yī","nián","chūn","hǎo","chù","，","jué","shèng","yān","liǔ","mǎn","huáng","dōu","。"]],"shiyi":"京城大道上空丝雨纷纷，它像酥油般细密而滋润，远望草色依稀连成一片，近看时却显得稀疏零星。\n这是一年中最美的季节，远胜过绿柳满城的春末。\n\n","zhushi":"呈：恭敬地送给。水部张十八员外：指张籍（766—830年）唐代诗人。在同族兄弟中排行第十八，曾任水部员外郎。\n天街：京城街道。润如酥：细腻如酥。酥，动物的油，这里形容春雨的细腻。\n最是：正是。处：时。\n绝胜：远远胜过。皇都：帝都，这里指长安。\n\n"},{"id":"k32","title":"渔歌子","author":"张志和","dynasty":"唐","paragraphs":["西塞山前白鹭飞，桃花流水鳜鱼肥。","青箬笠，绿蓑衣，斜风细雨不须归。"],"content_text":"西塞山前白鹭飞，桃花流水鳜鱼肥。青箬笠，绿蓑衣，斜风细雨不须归。","pinyin":[["xī","sāi","shān","qián","bái","lù","fēi","，","táo","huā","liú","shuǐ","jué","yú","féi","。"],["qīng","ruò","lì","，","lǜ","suō","yī","，","xié","fēng","xì","yǔ","bù","xū","guī","。"]],"shiyi":"西塞山前白鹭在自由地翱翔，江水中，肥美的鳜鱼欢快地游着，漂浮在水中的桃花是那样的鲜艳而饱满。\n江岸一位老翁戴着青色的箬笠，披着绿色的蓑衣，冒着斜风细雨，悠然自得地垂钓，他被美丽的春景迷住了，连下了雨都不回家。\n\n","zhushi":"渔歌子：词牌名。此调原为唐教坊名曲。分单调、双调二体。单调二十七字，平韵，以张氏此调最为著名。双调，五十字，仄韵。《渔歌子》又名《渔父》或《渔父乐》，大概是民间的渔歌。据《词林纪事》转引的记载说，张志和曾谒见湖州刺史颜真卿，因为船破旧了，请颜真卿帮助更换，并作《渔歌子》。词牌《渔歌子》即始于张志和写的《渔歌子》而得名。“子”即是“曲子”的简称。\n西塞山：浙江湖州。\n白鹭：一种白色的水鸟。\n桃花流水：桃花盛开的季节正是春水盛涨的时候，俗称桃花汛或桃花水。\n鳜（guì）鱼：淡水鱼，江南又称桂鱼，肉质鲜美。\n箬（ruò）笠：竹叶或竹蔑做的斗笠。\n蓑（suō）衣：用草或棕编制成的雨衣。\n不须：不一定要。\n\n"},{"id":"k33","title":"塞下曲","author":"卢纶","dynasty":"唐","paragraphs":["月黑雁飞高，单于夜遁逃。","欲将轻骑逐，大雪满弓刀。"],"content_text":"月黑雁飞高，单于夜遁逃。欲将轻骑逐，大雪满弓刀。","pinyin":[["yuè","hēi","yàn","fēi","gāo","，","dān","yú","yè","dùn","táo","。"],["yù","jiāng","qīng","qí","zhú","，","dà","xuě","mǎn","gōng","dāo","。"]],"shiyi":"夜静月黑雁群飞得很高，单于趁黑夜悄悄地逃窜。\n正要带领轻骑兵去追赶，大雪纷飞落满了身上的弓刀。\n\n","zhushi":"塞下曲：古时边塞的一种军歌。\n月黑：没有月光。\n单于（chán yú ）：匈奴的首领。这里指入侵者的最高统帅。\n遁：逃走。\n将：率领。\n轻骑：轻装快速的骑兵。\n逐：追赶。\n满：沾满。\n\n"},{"id":"k34","title":"望洞庭","author":"刘禹锡","dynasty":"唐","paragraphs":["湖光秋月两相和，潭面无风镜未磨。","遥望洞庭山水翠，白银盘里一青螺。(山水翠 一作：山水色)"],"content_text":"湖光秋月两相和，潭面无风镜未磨。遥望洞庭山水翠，白银盘里一青螺。(山水翠 一作：山水色)","pinyin":[["hú","guāng","qiū","yuè","liǎng","xiāng","hé","，","tán","miàn","wú","fēng","jìng","wèi","mó","。"],["yáo","wàng","dòng","tíng","shān","shuǐ","cuì","，","bái","yín","pán","lǐ","yī","qīng","luó","。","(","shān","shuǐ","cuì"," ","yī","zuò","：","shān","shuǐ","sè",")"]],"shiyi":"秋夜明月清辉，遍洒澄净湖面，湖面平静无风，犹如铁磨铜镜。\n遥望美丽洞庭的湖光山色。真的令人浮想联翩。那翠绿的君山，真像银盘里的一枚玲珑青螺。\n\n","zhushi":"洞庭：湖名，在今湖南省北部。\n湖光：湖面的波光。两：指湖光和秋月。和：和谐。指水色与月光互相辉映。\n潭面：指湖面。镜未磨：古人的镜子用铜制作、磨成。这里一说是湖面无风，水平如镜；一说是远望湖中的景物，隐约不清，如同镜面没打磨时照物模糊。\n山水翠：也作“山水色”。山：指洞庭湖中的君山。\n白银盘：形容平静而又清的洞庭湖面。白银：一作“白云”。青螺：这里用来形容洞庭湖中的君山。\n\n"},{"id":"k35","title":"浪淘沙","author":"刘禹锡","dynasty":"唐","paragraphs":["九曲黄河万里沙，浪淘风簸自天涯。","如今直上银河去，同到牵牛织女家。"],"content_text":"九曲黄河万里沙，浪淘风簸自天涯。如今直上银河去，同到牵牛织女家。","pinyin":[["jiǔ","qǔ","huáng","hé","wàn","lǐ","shā","，","làng","táo","fēng","bò","zì","tiān","yá","。"],["rú","jīn","zhí","shàng","yín","hé","qù","，","tóng","dào","qiān","niú","zhī","nǚ","jiā","。"]],"shiyi":"九曲黄河从遥远的地方蜿蜒奔腾而来，一路裹挟着万里的黄沙。\n既然你从天边而来，如今好像要直飞上高空的银河，请你带上我扶摇直上，汇集到银河中去，一同到牛郎和织女的家里做客吧。\n\n","zhushi":"浪淘沙：唐教坊曲名。创自刘禹锡、白居易，其形式为七言绝句。后又用为词牌名。\n九曲：自古相传黄河有九道弯。形容弯弯曲曲的地方很多。\n万里沙：黄河在流经各地时挟带大量泥沙。\n浪淘风簸：黄河卷着泥沙，风浪滚动的样子。浪淘：波浪淘洗。簸：掀翻，上下簸动。\n自天涯：来自天边。牵牛织女：银河系的两个星座名。自古相传，织女为天上仙女，下凡到人间，和牛郎结为夫妇。后西王母召回织女，牛郎追上天，西王母罚他们隔河相望，只准每年七月七日的夜晚相会一次。牵牛：即传说中的牛郎。\n\n"},{"id":"k36","title":"赋得古原草送别","author":"白居易","dynasty":"唐","paragraphs":["离离原上草，一岁一枯荣。","野火烧不尽，春风吹又生。","远芳侵古道，晴翠接荒城。","又送王孙去，萋萋满别情。"],"content_text":"离离原上草，一岁一枯荣。野火烧不尽，春风吹又生。远芳侵古道，晴翠接荒城。又送王孙去，萋萋满别情。","pinyin":[["lí","lí","yuán","shàng","cǎo","，","yī","suì","yī","kū","róng","。"],["yě","huǒ","shāo","bù","jìn","，","chūn","fēng","chuī","yòu","shēng","。"],["yuǎn","fāng","qīn","gǔ","dào","，","qíng","cuì","jiē","huāng","chéng","。"],["yòu","sòng","wáng","sūn","qù","，","qī","qī","mǎn","bié","qíng","。"]],"shiyi":"长长的原上草是多么茂盛，每年秋冬枯黄春来草色浓。\n无情的野火只能烧掉干叶，春风吹来大地又是绿茸茸。\n野草野花蔓延着淹没古道，艳阳下草地尽头是你征程。\n我又一次送走知心的好友，茂密的青草代表我的深情。\n\n","zhushi":"赋得：借古人诗句或成语命题作诗。诗题前一般都冠以“赋得”二字。这是古代人学习作诗或文人聚会分题作诗或科举考试时命题作诗的一种方式，称为“赋得体“。\n离离：青草茂盛的样子。\n一岁一枯荣：枯，枯萎。荣，茂盛。野草每年都会茂盛一次，枯萎一次。\n远芳侵古道：芳，指野草那浓郁的香气。远芳：草香远播。侵，侵占，长满。远处芬芳的野草一直长到古老的驿道上。\n晴翠：草原明丽翠绿。\n王孙：本指贵族后代，此指远方的友人。\n萋萋：形容草木长得茂盛的样子。\n\n"},{"id":"k37","title":"池上","author":"白居易","dynasty":"唐","paragraphs":["小娃撑小艇，偷采白莲回。","不解藏踪迹，浮萍一道开。"],"content_text":"小娃撑小艇，偷采白莲回。不解藏踪迹，浮萍一道开。","pinyin":[["xiǎo","wá","chēng","xiǎo","tǐng","，","tōu","cǎi","bái","lián","huí","。"],["bù","jiě","cáng","zōng","jì","，","fú","píng","yī","dào","kāi","。"]],"shiyi":"一个小孩撑着小船，偷偷地采了白莲回来。\n他不知道怎么掩藏踪迹，水面的浮萍上留下了一条船儿划过的痕迹。\n\n","zhushi":"小娃：男孩儿或女孩儿。艇：船。\n白莲：白色的莲花。\n踪迹：指被小艇划开的浮萍。\n浮萍：水生植物，椭圆形叶子浮在水面，叶下面有须根，夏季开白花。\n\n"},{"id":"k38","title":"忆江南","author":"白居易","dynasty":"唐","paragraphs":["江南好，风景旧曾谙。","日出江花红胜火，春来江水绿如蓝。","能不忆江南？"],"content_text":"江南好，风景旧曾谙。日出江花红胜火，春来江水绿如蓝。能不忆江南？","pinyin":[["jiāng","nán","hǎo","，","fēng","jǐng","jiù","céng","ān","。"],["rì","chū","jiāng","huā","hóng","shèng","huǒ","，","chūn","lái","jiāng","shuǐ","lǜ","rú","lán","。"],["néng","bù","yì","jiāng","nán","？"]],"shiyi":"江南的风景多么美好，如画的风景久已熟悉。春天到来时，太阳从江面升起，把江边的鲜花照得比火红，碧绿的江水绿得胜过蓝草。怎能叫人不怀念江南？\n\n","zhushi":"忆江南：唐教坊曲名。作者题下自注说：“此曲亦名‘谢秋娘’，每首五句。”按《乐府诗集》：“‘忆江南’一名‘望江南’，因白氏词，后遂改名‘江南好’。”至晚唐、五代成为词牌名。这里所指的江南主要是长江下游的江浙一带。\n谙（ān）：熟悉。作者年轻时曾三次到过江南。\n江花：江边的花朵。一说指江中的浪花。红胜火：颜色鲜红胜过火焰。\n绿如蓝：绿得比蓝还要绿。如，用法犹“于”，有胜过的意思。蓝，蓝草，其叶可制青绿染料。\n\n"},{"id":"k39","title":"小儿垂钓","author":"胡令能","dynasty":"唐","paragraphs":["蓬头稚子学垂纶，侧坐莓苔草映身。","路人借问遥招手，怕得鱼惊不应人。"],"content_text":"蓬头稚子学垂纶，侧坐莓苔草映身。路人借问遥招手，怕得鱼惊不应人。","pinyin":[["péng","tóu","zhì","zǐ","xué","chuí","lún","，","cè","zuò","méi","tái","cǎo","yìng","shēn","。"],["lù","rén","jiè","wèn","yáo","zhāo","shǒu","，","pà","dé","yú","jīng","bù","yìng","rén","。"]],"shiyi":"一个头发蓬乱、面孔青嫩的小孩在河边学着大人钓鱼，侧着身子坐在草丛中，野草掩映了他的身影。\n听到有过路的人问路，小孩漠不关心地摆了摆手，生怕惊动了鱼儿，不敢回应过路人。\n\n","zhushi":"蓬头：形容小孩可爱。稚子：年龄小的、懵懂的孩子。垂纶：钓鱼。纶：钓鱼用的丝线。\n莓：一种野草。苔：苔藓植物。映：遮映。\n借问：向人打听。\n鱼惊：鱼儿受到惊吓。应：回应，答应，理睬。\n\n"},{"id":"k40","title":"悯农","author":"李绅","dynasty":"唐","paragraphs":["锄禾日当午，汗滴禾下土。","谁知盘中餐，粒粒皆辛苦？"],"content_text":"锄禾日当午，汗滴禾下土。谁知盘中餐，粒粒皆辛苦？","pinyin":[["chú","hé","rì","dāng","wǔ","，","hàn","dī","hé","xià","tǔ","。"],["shuí","zhī","pán","zhōng","cān","，","lì","lì","jiē","xīn","kǔ","？"]],"shiyi":"春天只要播下一粒种子，秋天就可收获很多粮食。\n普天之下，没有荒废不种的田地，劳苦农民，仍然要饿死。\n\n盛夏中午，烈日炎炎，农民还在劳作，汗珠滴入泥土。\n有谁想到，我们碗中的米饭，粒粒饱含着农民的血汗？\n\n","zhushi":"悯：怜悯。这里有同情的意思。诗一作《古风二首》。这两首诗的排序各版本有所不同。\n粟：泛指谷类。\n秋收：一作“秋成”。子：指粮食颗粒。\n四海：指全国。闲田：没有耕种的田。\n犹：仍然。\n禾：谷类植物的统称。\n餐：一作“飧”。熟食的通称。\n\n"},{"id":"k41","title":"悯农","author":"李绅","dynasty":"唐","paragraphs":["春种一粒粟，秋收万颗子。","四海无闲田，农夫犹饿死。"],"content_text":"春种一粒粟，秋收万颗子。四海无闲田，农夫犹饿死。","pinyin":[["chūn","zhǒng","yī","lì","sù","，","qiū","shōu","wàn","kē","zǐ","。"],["sì","hǎi","wú","xián","tián","，","nóng","fū","yóu","è","sǐ","。"]],"shiyi":"春天只要播下一粒种子，秋天就可收获很多粮食。\n普天之下，没有荒废不种的田地，劳苦农民，仍然要饿死。\n\n盛夏中午，烈日炎炎，农民还在劳作，汗珠滴入泥土。\n有谁想到，我们碗中的米饭，粒粒饱含着农民的血汗？\n\n","zhushi":"悯：怜悯。这里有同情的意思。诗一作《古风二首》。这两首诗的排序各版本有所不同。\n粟：泛指谷类。\n秋收：一作“秋成”。子：指粮食颗粒。\n四海：指全国。闲田：没有耕种的田。\n犹：仍然。\n禾：谷类植物的统称。\n餐：一作“飧”。熟食的通称。\n\n"},{"id":"k42","title":"江雪","author":"柳宗元","dynasty":"唐","paragraphs":["千山鸟飞绝，万径人踪灭。","孤舟蓑笠翁，独钓寒江雪。"],"content_text":"千山鸟飞绝，万径人踪灭。孤舟蓑笠翁，独钓寒江雪。","pinyin":[["qiān","shān","niǎo","fēi","jué","，","wàn","jìng","rén","zōng","miè","。"],["gū","zhōu","suō","lì","wēng","，","dú","diào","hán","jiāng","xuě","。"]],"shiyi":"所有的山，飞鸟全都断绝；所有的路，不见人影踪迹。\n江上孤舟，渔翁披蓑戴笠；独自垂钓，不怕冰雪侵袭。\n\n","zhushi":"绝：无，没有。\n万径：虚指，指千万条路。\n人踪：人的脚印。\n孤：孤零零。\n蓑笠（suō lì）：蓑衣和斗笠　笠：用竹篾编成的帽子。\n独：独自。\n\n"},{"id":"k43","title":"寻隐者不遇","author":"贾岛","dynasty":"唐","paragraphs":["松下问童子，言师采药去。","只在此山中，云深不知处。"],"content_text":"松下问童子，言师采药去。只在此山中，云深不知处。","pinyin":[["sōng","xià","wèn","tóng","zǐ","，","yán","shī","cǎi","yào","qù","。"],["zhī","zài","cǐ","shān","zhōng","，","yún","shēn","bù","zhī","chù","。"]],"shiyi":"苍松下，我询问了年少的学童；他说，师傅已经采药去了山中。\n他还对我说，就在这座大山里，可山中云雾缭绕，不知他行踪。\n\n","zhushi":"⑴寻：寻访。隐者：隐士，隐居在山林中的人。古代指不肯做官而隐居在山野之间的人。一般指的是贤士。不遇：没有遇到，没有见到。\n⑵童子：没有成年的人，小孩。在这里是指“隐者”的弟子、学生。\n⑶言：回答，说。\n⑷云深：指山上的云雾。处：行踪，所在。\n\n"},{"id":"k44","title":"山行","author":"杜牧","dynasty":"唐","paragraphs":["远上寒山石径斜，白云深处有人家。(深处 一作：生处)","停车坐爱枫林晚，霜叶红于二月花。"],"content_text":"远上寒山石径斜，白云深处有人家。(深处 一作：生处)停车坐爱枫林晚，霜叶红于二月花。","pinyin":[["yuǎn","shàng","hán","shān","shí","jìng","xié","，","bái","yún","shēn","chù","yǒu","rén","jiā","。","(","shēn","chù"," ","yī","zuò","：","shēng","chù",")"],["tíng","chē","zuò","ài","fēng","lín","wǎn","，","shuāng","yè","hóng","yú","èr","yuè","huā","。"]],"shiyi":"沿着弯弯曲曲的小路上山，在那白云深处，居然还有人家。\n停下车来，是因为喜爱这深秋枫林晚景。枫叶秋霜染过，艳比二月春花。\n\n","zhushi":"山行：在山中行走。\n远上：登上远处的。\n寒山：深秋季节的山。\n石径：石子的小路。\n斜：为倾斜的意思。\n深：另有版本作“生”。（“深”可理解为在云雾缭绕的的深处； “生”可理解为在形成白云的地方）\n车：轿子。\n坐：因为。\n霜叶：枫树的叶子经深秋寒霜之后变成了红色。\n枫林晚：傍晚时的枫树林。\n红于：比……更红，本文指霜叶红于二月花。\n\n"},{"id":"k45","title":"清明","author":"杜牧","dynasty":"唐","paragraphs":["清明时节雨纷纷，路上行人欲断魂。","借问酒家何处有，牧童遥指杏花村。"],"content_text":"清明时节雨纷纷，路上行人欲断魂。借问酒家何处有，牧童遥指杏花村。","pinyin":[["qīng","míng","shí","jié","yǔ","fēn","fēn","，","lù","shàng","xíng","rén","yù","duàn","hún","。"],["jiè","wèn","jiǔ","jiā","hé","chù","yǒu","，","mù","tóng","yáo","zhǐ","xìng","huā","cūn","。"]],"shiyi":"江南清明时节细雨纷纷飘洒，路上羁旅行人个个落魄断魂。\n借问当地之人何处买酒浇愁？牧童笑而不答遥指杏花山村。\n\n","zhushi":"清明：二十四节气之一，在阳历四月五日前后。旧俗当天有扫墓、踏青、插柳等活动。宫中以当天为秋千节，坤宁宫及各后宫都安置秋千，嫔妃做秋千之戏。\n纷纷：形容多。\n欲断魂：形容伤感极深，好像灵魂要与身体分开一样。断魂：神情凄迷，烦闷不乐。这两句是说，清明时候，阴雨连绵，飘飘洒洒下个不停；如此天气，如此节日，路上行人情绪低落，神魂散乱。\n借问：请问。\n杏花村：杏花深处的村庄。今在安徽贵池秀山门外。受此诗影响，后人多用“杏花村”作酒店名。\n\n"},{"id":"k46","title":"江南春","author":"杜牧","dynasty":"唐","paragraphs":["千里莺啼绿映红，水村山郭酒旗风。","南朝四百八十寺，多少楼台烟雨中。"],"content_text":"千里莺啼绿映红，水村山郭酒旗风。南朝四百八十寺，多少楼台烟雨中。","pinyin":[["qiān","lǐ","yīng","tí","lǜ","yìng","hóng","，","shuǐ","cūn","shān","guō","jiǔ","qí","fēng","。"],["nán","cháo","sì","bǎi","bā","shí","sì","，","duō","shǎo","lóu","tái","yān","yǔ","zhōng","。"]],"shiyi":"江南大地鸟啼声声绿草红花相映，水边村寨山麓城郭处处酒旗飘动。\n南朝遗留下的四百八十多座古寺，无数的楼台全笼罩在风烟云雨中。\n\n","zhushi":"莺啼：即莺啼燕语。\n郭：外城。此处指城镇。\n酒旗：一种挂在门前以作为酒店标记的小旗。\n南朝：指先后与北朝对峙的宋、齐、梁、陈政权。\n四百八十寺：南朝皇帝和大官僚好佛，在京城（今南京市）大建佛寺。这里说四百八十寺，是虚数。\n楼台：楼阁亭台。此处指寺院建筑。\n烟雨：细雨蒙蒙，如烟如雾。\n\n"},{"id":"k47","title":"蜂","author":"罗隐","dynasty":"唐","paragraphs":["不论平地与山尖，无限风光尽被占。","采得百花成蜜后，为谁辛苦为谁甜？"],"content_text":"不论平地与山尖，无限风光尽被占。采得百花成蜜后，为谁辛苦为谁甜？","pinyin":[["bù","lùn","píng","dì","yǔ","shān","jiān","，","wú","xiàn","fēng","guāng","jìn","bèi","zhàn","。"],["cǎi","dé","bǎi","huā","chéng","mì","hòu","，","wèi","shuí","xīn","kǔ","wèi","shuí","tián","？"]],"shiyi":"无论是在平地，还是在那高山，哪里鲜花迎风盛开，哪里就有蜜蜂奔忙。\n蜜蜂啊，你采尽百花酿成了花蜜，到底为谁付出辛苦，又想让谁品尝香甜？\n\n","zhushi":"山尖：山峰。\n尽：都。\n占：占其所有。\n甜：醇香的蜂蜜。\n\n"},{"id":"k48","title":"江上渔者","author":"范仲淹","dynasty":"宋","paragraphs":["江上往来人，但爱鲈鱼美。","君看一叶舟，出没风波里。"],"content_text":"江上往来人，但爱鲈鱼美。君看一叶舟，出没风波里。","pinyin":[["jiāng","shàng","wǎng","lái","rén","，","dàn","ài","lú","yú","měi","。"],["jūn","kàn","yī","yè","zhōu","，","chū","méi","fēng","bō","lǐ","。"]],"shiyi":"白话译文\n江上来来往往的人只喜爱鲈鱼的味道鲜美。\n看看那些可怜的打鱼人吧，正驾着小船在大风大浪里上下颠簸，飘摇不定。\n\n英文译文\nTHE FISHERMAN ON THE STREAM\nYou go up and down stream;\nYou love to eat the bream.\nLo! The fishing boat braves\nPerilous wind and waves.\n\n","zhushi":"①渔者：捕鱼的人。\n②但：只\n江上渔者\n江上渔者\n③爱：喜欢\n④鲈鱼：一种头大口大、体扁鳞细、背青腹白、 味道鲜美的鱼。 生长快，体大味美。\n⑤君：你。\n⑥一叶舟：像漂浮在水上的一片树叶似的小船。\n⑦出没：若隐若现。指一会儿看得见，一会儿看不见。\n⑧风波：波浪。\n\n"},{"id":"k49","title":"元日","author":"王安石","dynasty":"宋","paragraphs":["爆竹声中一岁除，春风送暖入屠苏。","千门万户曈曈日，总把新桃换旧符。"],"content_text":"爆竹声中一岁除，春风送暖入屠苏。千门万户曈曈日，总把新桃换旧符。","pinyin":[["bào","zhú","shēng","zhōng","yī","suì","chú","，","chūn","fēng","sòng","nuǎn","rù","tú","sū","。"],["qiān","mén","wàn","hù","tóng","tóng","rì","，","zǒng","bǎ","xīn","táo","huàn","jiù","fú","。"]],"shiyi":"阵阵轰鸣的爆竹声中，旧的一年已经过去；和暖的春风吹来了新年，人们欢乐地畅饮着新酿的屠苏酒。\n初升的太阳照耀着千家万户，他们都忙着把旧的桃符取下，换上新的桃符。\n\n","zhushi":"元日：农历正月初一，即春节。\n爆竹：古人烧竹子时使竹子爆裂发出的响声。用来驱鬼避邪，后来演变成放鞭炮。一岁除：一年已尽。除，逝去。\n屠苏：“指屠苏酒，饮屠苏酒也是古代过年时的一种习俗，大年初一全家合饮这种用屠苏草浸泡的酒，以驱邪避瘟疫，求得长寿。\n千门万户：形容门户众多，人口稠密。曈曈：日出时光亮而温暖的样子。\n桃：桃符，古代一种风俗，农历正月初一时人们用桃木板写上神荼、郁垒两位神灵的名字，悬挂在门旁，用来压邪。也作春联。\n\n"},{"id":"k50","title":"泊船瓜洲","author":"王安石","dynasty":"宋","paragraphs":["京口瓜洲一水间，钟山只隔数重山。","春风又绿江南岸，明月何时照我还？"],"content_text":"京口瓜洲一水间，钟山只隔数重山。春风又绿江南岸，明月何时照我还？","pinyin":[["jīng","kǒu","guā","zhōu","yī","shuǐ","jiān","，","zhōng","shān","zhī","gé","shù","zhòng","shān","。"],["chūn","fēng","yòu","lǜ","jiāng","nán","àn","，","míng","yuè","hé","shí","zhào","wǒ","hái","？"]],"shiyi":"京口和瓜洲不过一水之遥，钟山也只隔着几重青山。\n温柔的春风又吹绿了大江南岸，可是，天上的明月呀，你什么时候才能够照着我回家呢？\n\n","zhushi":"泊船：停船。泊，停泊。指停泊靠岸。\n绿：吹绿。\n京口：古城名。故址在江苏镇江市。\n瓜洲：镇名，在长江北岸，扬州南郊，即今扬州市南部长江边,京杭运河分支入江处。\n一水：一条河。古人除将黄河特称为“河”，长江特称为“江”之外，大多数情况下称河流为“水”，如\n汝水、汉水、浙水、湘水、澧水等等。这里的“一水”指长江。一水间指一水相隔之间。\n钟山：在江苏省南京市区东。\n\n\n"},{"id":"k51","title":"书湖阴先生壁","author":"王安石","dynasty":"宋","paragraphs":["茅檐长扫净无苔，花木成畦手自栽。","一水护田将绿绕，两山排闼送青来。"],"content_text":"茅檐长扫净无苔，花木成畦手自栽。一水护田将绿绕，两山排闼送青来。","pinyin":[["máo","yán","cháng","sǎo","jìng","wú","tái","，","huā","mù","chéng","qí","shǒu","zì","zāi","。"],["yī","shuǐ","hù","tián","jiāng","lǜ","rào","，","liǎng","shān","pái","tà","sòng","qīng","lái","。"]],"shiyi":"茅草房庭院经常打扫，洁净得没有一丝青苔。花草树木成行成垄，都是主人亲手栽种。\n庭院外一条小河保护着农田，并且环绕着农田；两座大山打开门来为人们送去绿色。\n\n桑树枝叶繁茂，楝花也十分繁盛。清风吹送楝花余香，悄悄地送过墙头。 \n黄莺几声清脆的啼叫 ，惊醒了我的午觉。一梦醒来，我恍恍惚惚还觉得自己好像仍然在旧日所住的半山园中。\n\n","zhushi":"书：书写，题诗。湖阴先生：本名杨德逢，隐居之士，是王安石晚年居住金陵紫金山（今江苏南京）时的邻居。\n茅檐：茅屋檐下，这里指庭院。无苔：没有青苔。\n成畦（qí ）：成垄成行。 畦：经过修整的一块块田地。\n护田：这里指护卫环绕着园田。⑸排闼（tà）：开门。闼：小门。送青来：送来绿色。\n楝(liàn)花：“二十四番花信”里的楝花，指的就是北方常见的苦楝花。\n\n"},{"id":"k52","title":"六月二十七日望湖楼醉书","author":"苏轼","dynasty":"宋","paragraphs":["黑云翻墨未遮山，白雨跳珠乱入船。","卷地风来忽吹散，望湖楼下水如天。"],"content_text":"黑云翻墨未遮山，白雨跳珠乱入船。卷地风来忽吹散，望湖楼下水如天。","pinyin":[["hēi","yún","fān","mò","wèi","zhē","shān","，","bái","yǔ","tiào","zhū","luàn","rù","chuán","。"],["juàn","dì","fēng","lái","hū","chuī","sàn","，","wàng","hú","lóu","xià","shuǐ","rú","tiān","。"]],"shiyi":"乌云上涌，就如墨汁泼下，却又在天边露出一段山峦，明丽清新，大雨激起的水花如白珠碎石，飞溅入船。\n忽然间狂风卷地而来，吹散了满天的乌云，而那西湖的湖水碧波如镜，明媚温柔。\n\n放生出去的鱼鳖追赶着人们来，到处都开着不知谁种的荷花。\n躺在船里的枕席上可以觉得山在一俯一仰地晃动，飘荡在风里的船也知道和月亮徘徊留连不已。\n\n湖里生长的乌菱和白芡不用论钱，水中的雕胡米就像包裹在绿盘里。\n忽然回忆起在会灵观尝食新谷之事，如要滞留在江海之上需多进饮食，保重身体啊。\n\n兰舟上的采莲女把湖上的荷花采下来送给游人，在细雨斜风里，她们头上的翠翘被打湿。\n芳草丛生的小洲上长满了香草，这些采莲女又如何能一一认识？\n\n做不到隐居山林，暂时先做个闲官吧，这样尚可得到长期的悠闲胜过暂时的休闲。\n我本来就没有家，不安身在这里又能到哪里去呢?何况就算是故乡，也没有像这里这样优美的湖光山色。\n\n","zhushi":"六月二十七日：指宋神宗熙宁五年（1072）六月二十七日。望湖楼：古建筑名，又叫看经楼。位于杭州西湖畔，五代时吴越王钱弘俶（又名钱弘）所建。醉书：饮酒醉时写下的作品。\n翻墨：打翻的黑墨水，形容云层很黑。遮：遮盖，遮挡。\n白雨：指夏日阵雨的特殊景观，因雨点大而猛，在湖光山色的衬托下，显得白而透明。跳珠：跳动的水珠（珍珠），用“跳珠”形容雨点，说明雨点大，杂乱无序。\n卷地风来：指狂风席地卷来。又如，韩退之《双鸟》诗：“春风卷地起，百鸟皆飘浮。”忽：突然。\n水如天：形容湖面像天空一般开阔而且平静。\n放生鱼鳖：北宋时杭州的官吏曾规定西湖为放生地，不许人打鱼，替皇帝延寿添福。\n“水枕”句：躺在船里看山，不觉得水波起落，只见山头忽上忽下。水枕，等于“载在水面的枕席”。\n风船：指的是“飘荡在风里的船”。裴回：即徘徊。\n乌菱：指老菱。菱角老则壳黑，故名。芡（qiàn）：大型水生植物。\n青菰（gū）：俗称茭白。生于河边、沼泽地。可作蔬菜。其实如米，称雕胡米，可作饭。\n尝新：古代于孟秋以新收获的五谷祭祀祖先，然后尝食新谷。\n游女：出游的女子。 木兰桡：常用为船的美称，并非实指木兰木所制。桡（ráo）：划船的桨，这里指小船。\n翠翘：古代妇女首饰的一种，状似翠鸟尾上的长羽，故名。\n芳洲：芳草丛生的小洲。杜若：香草名。多年生草本，高一二尺。叶广披针形，味辛香。\n吴儿：指吴地之人，这里也代指采莲女。吴地，指现中国长江下游南岸一带地域的一个总称。\n小隐：谓隐居山林。 \n\n"},{"id":"k53","title":"饮湖上初晴后雨","author":"苏轼","dynasty":"宋","paragraphs":["水光潋滟晴方好，山色空蒙雨亦奇。(蒙 通：濛)","欲把西湖比西子，淡妆浓抹总相宜。"],"content_text":"水光潋滟晴方好，山色空蒙雨亦奇。(蒙 通：濛)欲把西湖比西子，淡妆浓抹总相宜。","pinyin":[["shuǐ","guāng","liàn","yàn","qíng","fāng","hǎo","，","shān","sè","kōng","méng","yǔ","yì","qí","。","(","méng"," ","tōng","：","méng",")"],["yù","bǎ","xī","hú","bǐ","xī","zǐ","，","dàn","zhuāng","nóng","mǒ","zǒng","xiāng","yí","。"]],"shiyi":"在灿烂的阳光照耀下，西湖水微波粼粼，波光艳丽，看起来很美；雨天时，在雨幕的笼罩下，西湖周围的群山迷迷茫茫，若有若无，也显得非常奇妙。\n若把西湖比作古美女西施，淡妆浓抹都是那么得十分适宜。\n\n","zhushi":"湖：即杭州西湖。\n潋滟(liàn yàn) ：水面波光闪动的样子。\n方好：正是显得很美。\n空濛：细雨迷茫的样子。\n西子：西施，春秋时代越国有名的美女，原名施夷光，或称 先施 ，居古代四大美女（西施、王昭君、貂蝉、杨玉环）之首。家住浣纱溪村（在今浙江诸暨市）西，所以称为西施。\n相宜：也显得十分美丽。\n\n"},{"id":"k54","title":"惠崇春江晚景","author":"苏轼","dynasty":"宋","paragraphs":["竹外桃花三两枝，春江水暖鸭先知。","蒌蒿满地芦芽短，正是河豚欲上时。"],"content_text":"竹外桃花三两枝，春江水暖鸭先知。蒌蒿满地芦芽短，正是河豚欲上时。","pinyin":[["zhú","wài","táo","huā","sān","liǎng","zhī","，","chūn","jiāng","shuǐ","nuǎn","yā","xiān","zhī","。"],["lóu","hāo","mǎn","dì","lú","yá","duǎn","，","zhèng","shì","hé","tún","yù","shàng","shí","。"]],"shiyi":"竹林外两三枝桃花初放，鸭子在水中游戏，它们最先察觉了初春江水的回暖。\n河滩上已经满是蒌蒿，芦笋也开始抽芽，而河豚此时正要逆流而上，从大海回游到江河里来了。\n\n大雁北飞，就像要回到北方家乡的人那样，但是由于依恋，差一点掉了队。\n还没有飞到北方时，就已经知道北方的沙漠多风雪了，还是再在江南渡过半月的春光时节吧。\n\n","zhushi":"惠崇（亦为慧崇）：福建建阳僧，宋初九僧之一，能诗能画。《春江晚景》是惠崇所作画名，共两幅，一幅是鸭戏图，一幅是飞雁图。钱钟书《宋诗选注》中为“晓景”。诸多注本，有用“晓景”、有用“晚景”，此从《东坡全集》及清以前注本用“晚景”。这两诗是作者元丰八年春天在靖江欲南返时江边情景的写照。\n蒌蒿：草名，有青蒿、白蒿等种。芦芽：芦苇的幼芽，可食用。\n河豚：鱼的一种，学名“鲀”，肉味鲜美，但是卵巢和肝脏有剧毒。产于我国沿海和一些内河。每年春天逆江而上，在淡水中产卵。上：指逆江而上。\n归鸿：归雁。破群：离开飞行队伍。\n依依：不舍之貌。归人：回家的人。\n朔漠：北方沙漠之地。杜甫诗：“一去紫台连朔漠。”\n更待：再等；再过。\n\n"},{"id":"k55","title":"题西林壁","author":"苏轼","dynasty":"宋","paragraphs":["横看成岭侧成峰，远近高低各不同。","不识庐山真面目，只缘身在此山中。"],"content_text":"横看成岭侧成峰，远近高低各不同。不识庐山真面目，只缘身在此山中。","pinyin":[["héng","kàn","chéng","lǐng","cè","chéng","fēng","，","yuǎn","jìn","gāo","dī","gè","bù","tóng","。"],["bù","shí","lú","shān","zhēn","miàn","mù","，","zhī","yuán","shēn","zài","cǐ","shān","zhōng","。"]],"shiyi":"从正面、侧面看庐山山岭连绵起伏、山峰耸立，从远处、近处、高处、低处看庐山，庐山呈现各种不同的样子。\n我之所以认不清庐山真正的面目，是因为我人身处在庐山之中。\n\n","zhushi":"题西林壁：写在西林寺的墙壁上。西林寺在庐山西麓。题：书写，题写。西林：西林寺，在江西庐山。\n横看：从正面看。庐山总是南北走向，横看就是从东面西面看.\n侧：侧面。\n各不同：各不相同。\n不识：不能认识，辨别。\n真面目：指庐山真实的景色，形状。\n缘：因为；由于。\n此山：这座山，指庐山。\n西林：西林寺，在现在江西省的庐山上。这首诗是题在寺里墙壁上的。\n\n"},{"id":"k56","title":"夏日绝句","author":"李清照","dynasty":"宋","paragraphs":["生当作人杰，死亦为鬼雄。","至今思项羽，不肯过江东。"],"content_text":"生当作人杰，死亦为鬼雄。至今思项羽，不肯过江东。","pinyin":[["shēng","dāng","zuò","rén","jié","，","sǐ","yì","wèi","guǐ","xióng","。"],["zhì","jīn","sī","xiàng","yǔ","，","bù","kěn","guò","jiāng","dōng","。"]],"shiyi":"生时应当做人中豪杰，死后也要做鬼中英雄。\n到今天人们还在怀念项羽，因为他不肯苟且偷生，退回江东。\n\n","zhushi":"人杰：人中的豪杰。汉高祖曾称赞开国功臣张良、萧何、韩信是“人杰”。\n鬼雄：鬼中的英雄。\n项羽：秦末时自立为西楚霸王，与刘邦争夺天下，在垓下之战中，兵败自杀。\n江东：项羽当初随叔父项梁起兵的地方。\n\n"},{"id":"k57","title":"三衢道中","author":"曾几","dynasty":"宋","paragraphs":["梅子黄时日日晴，小溪泛尽却山行。","绿阴不减来时路，添得黄鹂四五声。"],"content_text":"梅子黄时日日晴，小溪泛尽却山行。绿阴不减来时路，添得黄鹂四五声。","pinyin":[["méi","zǐ","huáng","shí","rì","rì","qíng","，","xiǎo","xī","fàn","jìn","què","shān","xíng","。"],["lǜ","yīn","bù","jiǎn","lái","shí","lù","，","tiān","dé","huáng","lí","sì","wǔ","shēng","。"]],"shiyi":"梅子黄透了的时候，天天都是晴朗的好天气，乘小舟沿着小溪而行，走到了小溪的尽头，再改走山路继续前行。\n山路上苍翠的树，与来的时候一样浓密，深林丛中传来几声黄鹂的欢鸣声，比来时更增添了些幽趣。\n\n","zhushi":"三衢道中：在去三衢州的道路上。三衢即衢州，今浙江省常山县，因境内有三衢山而得名。\n梅子黄时：指五月，梅子成熟的季节。\n小溪泛尽：乘小船走到小溪的尽头。小溪，小河沟。泛，乘船。尽，尽头。\n却山行：再走山间小路。却，再的意思。\n绿阴：苍绿的树阴。阴，树阴。\n不减：并没有少多少，差不多。\n黄鹂：黄莺。\n\n"},{"id":"k58","title":"示儿","author":"陆游","dynasty":"宋","paragraphs":["死去元知万事空，但悲不见九州同。","王师北定中原日，家祭无忘告乃翁。"],"content_text":"死去元知万事空，但悲不见九州同。王师北定中原日，家祭无忘告乃翁。","pinyin":[["sǐ","qù","yuán","zhī","wàn","shì","kōng","，","dàn","bēi","bù","jiàn","jiǔ","zhōu","tóng","。"],["wáng","shī","běi","dìng","zhōng","yuán","rì","，","jiā","jì","wú","wàng","gào","nǎi","wēng","。"]],"shiyi":"我本来知道，当我死后，人间的一切就都和我无关了；但唯一使我痛心的，就是我没能亲眼看到祖国的统一。\n因此，当大宋军队收复了中原失地的那一天到来之时，你们举行家祭，千万别忘把这好消息告诉我！\n\n","zhushi":"示儿：写给儿子们看。\n元知：原本知道。元，通“原”。本来。在苏教版等大部分教材中本诗第一句为“死去元知万事空”，但在老的人教版等教材中为“死去原知万事空”，因为是通假字，所以并不影响本诗的意境，尚有争议。人教版等教材多为“元”，不常用通假字。\n万事空：什么也没有了。\n但：只是。\n悲：悲伤\n九州：这里代指宋代的中国。古代中国分为九州，所以常用九州指代中国。\n同：统一。\n王师：指南宋朝廷的军队。\n北定：将北方平定。\n中原：指淮河以北被金人侵占的地区。\n家祭：祭祀家中先人。\n无忘：不要忘记。\n乃翁：你的父亲，指陆游自己。\n\n"},{"id":"k59","title":"秋夜将晓出篱门迎凉有感","author":"陆游","dynasty":"宋","paragraphs":["三万里河东入海，五千仞岳上摩天。","遗民泪尽胡尘里，南望王师又一年。"],"content_text":"三万里河东入海，五千仞岳上摩天。遗民泪尽胡尘里，南望王师又一年。","pinyin":[["sān","wàn","lǐ","hé","dōng","rù","hǎi","，","wǔ","qiān","rèn","yuè","shàng","mó","tiān","。"],["yí","mín","lèi","jìn","hú","chén","lǐ","，","nán","wàng","wáng","shī","yòu","yī","nián","。"]],"shiyi":"迢迢万里的银河朝西南方向下坠，喔喔的鸡叫之声在邻家不断长鸣。\n疾病折磨我几乎把救亡壮志消尽，出门四望不禁手搔白发抱憾平生。\n\n三万里长的黄河奔腾向东流入大海，五千仞高的华山耸入云霄上摩青天。\n中原人民在胡人压迫下眼泪已流尽，他们盼望王师北伐盼了一年又一年。\n\n","zhushi":"将晓：天将要亮。篱门：竹子或树枝编的门。迎凉：出门感到一阵凉风。\n天汉：银河。《诗经·小雅·大东》：“维天有汉，监亦有光。”毛传：“汉，天河也。”\n搔首：以手搔头。焦急或有所思貌。怆（chuàng）：悲伤。\n三万里：长度，形容它的长，是虚指。河：指黄河。\n五千仞（rèn）：形容它的高。仞，古代计算长度的一种单位，周尺八尺或七尺，周尺一尺约合二十三厘米。岳：指五岳之一西岳华山。黄河和华山都在金人占领区内。一说指北方泰、恒、嵩、华诸山。摩天：迫近高天，形容极高。摩，摩擦、接触或触摸。\n遗民：指在金占领区生活的汉族人民，却认同南宋王朝统治的人民。泪尽：眼泪流干了，形容十分悲惨、痛苦。胡尘：指金人入侵中原，也指胡人骑兵的铁蹄践踏扬起的尘土和金朝的暴政。胡，中国古代对北方和西方少数民族的泛称。\n南望：远眺南方。王师：指宋朝的军队。\n\n"},{"id":"k60","title":"四时田园杂兴","author":"范成大","dynasty":"宋","paragraphs":["昼出耘田夜绩麻，村庄儿女各当家。","童孙未解供耕织，也傍桑阴学种瓜。"],"content_text":"昼出耘田夜绩麻，村庄儿女各当家。童孙未解供耕织，也傍桑阴学种瓜。","pinyin":[["zhòu","chū","yún","tián","yè","jì","má","，","cūn","zhuāng","ér","nǚ","gè","dāng","jiā","。"],["tóng","sūn","wèi","jiě","gòng","gēng","zhī","，","yě","bàng","sāng","yīn","xué","zhǒng","guā","。"]],"shiyi":"白天在田里锄草，夜晚在家中搓麻线，村中男男女女各有各的家务劳动。\n小孩子虽然不会耕田织布，也在那桑树阴下学着种瓜。\n\n","zhushi":"耘田：除草。绩麻：把麻搓成线。各当家：每人担任一定的工作。未解：不懂。供：从事，参加。傍：靠近。\n\n"},{"id":"k61","title":"四时田园杂兴","author":"范成大","dynasty":"宋","paragraphs":["梅子金黄杏子肥，麦花雪白菜花稀。","日长篱落无人过，惟有蜻蜓蛱蝶飞。(惟 通 唯)"],"content_text":"梅子金黄杏子肥，麦花雪白菜花稀。日长篱落无人过，惟有蜻蜓蛱蝶飞。(惟 通 唯)","pinyin":[["méi","zǐ","jīn","huáng","xìng","zǐ","féi","，","mài","huā","xuě","bái","cài","huā","xī","。"],["rì","cháng","lí","luò","wú","rén","guò","，","wéi","yǒu","qīng","tíng","jiá","dié","fēi","。","(","wéi"," ","tōng"," ","wéi",")"]],"shiyi":"一树树梅子变得金黄，杏子也越长越大了；荞麦花一片雪白，油菜花倒显得稀稀落落。\n白天长了，篱笆的影子随着太阳的升高变得越来越短，没有人经过；只有蜻蜓和蝴蝶绕着篱笆飞来飞去。\n\n","zhushi":"篱落：篱笆。\n\n"},{"id":"k62","title":"小池","author":"杨万里","dynasty":"宋","paragraphs":["泉眼无声惜细流，树阴照水爱晴柔。","小荷才露尖尖角，早有蜻蜓立上头。"],"content_text":"泉眼无声惜细流，树阴照水爱晴柔。小荷才露尖尖角，早有蜻蜓立上头。","pinyin":[["quán","yǎn","wú","shēng","xī","xì","liú","，","shù","yīn","zhào","shuǐ","ài","qíng","róu","。"],["xiǎo","hé","cái","lù","jiān","jiān","jiǎo","，","zǎo","yǒu","qīng","tíng","lì","shàng","tóu","。"]],"shiyi":"泉眼悄然无声是因舍不得细细的水流，树荫倒映水面是喜爱晴天和风的轻柔。\n娇嫩的小荷叶刚从水面露出尖尖的角，早有一只调皮的小蜻蜓立在它的上头。\n\n","zhushi":"泉眼：泉水的出口。惜：吝惜。\n照水：映在水里。晴柔：晴天里柔和的风光。\n尖尖角：初出水端还没有舒展的荷叶尖端。\n上头：上面，顶端。为了押韵，“头”不读轻声。\n\n"},{"id":"k63","title":"晓出净慈寺送林子方","author":"杨万里","dynasty":"宋","paragraphs":["毕竟西湖六月中，风光不与四时同。","接天莲叶无穷碧，映日荷花别样红。"],"content_text":"毕竟西湖六月中，风光不与四时同。接天莲叶无穷碧，映日荷花别样红。","pinyin":[["bì","jìng","xī","hú","liù","yuè","zhōng","，","fēng","guāng","bù","yǔ","sì","shí","tóng","。"],["jiē","tiān","lián","yè","wú","qióng","bì","，","yìng","rì","hé","huā","bié","yàng","hóng","。"]],"shiyi":"到底是西湖六月天的景色，风光与其它季节确实不同。\n荷叶接天望不尽一片碧绿，阳光下荷花分外艳丽鲜红。\n\n","zhushi":"晓出：太阳刚刚升起。\n净慈寺：全名“净慈报恩光孝禅寺”，与灵隐寺为杭州西湖南北山两大著名佛寺。\n林子方：作者的朋友，官居直阁秘书。\n毕竟： 到底。\n六月中：六月的时候。\n四时：春夏秋冬四个季节。在这里指六月以外的其他时节。\n同：相同。\n接天：像与天空相接。\n无穷：无边无际。无穷碧：因莲叶面积很广，似与天相接，故呈现无穷的碧绿。\n映日：太阳映照。\n别样：宋代俗语，特别，不一样。别样红：红得特别出色。\n\n"},{"id":"k64","title":"春日","author":"朱熹","dynasty":"宋","paragraphs":["胜日寻芳泗水滨，无边光景一时新。","等闲识得东风面，万紫千红总是春。"],"content_text":"胜日寻芳泗水滨，无边光景一时新。等闲识得东风面，万紫千红总是春。","pinyin":[["shèng","rì","xún","fāng","sì","shuǐ","bīn","，","wú","biān","guāng","jǐng","yī","shí","xīn","。"],["děng","xián","shí","dé","dōng","fēng","miàn","，","wàn","zǐ","qiān","hóng","zǒng","shì","chūn","。"]],"shiyi":"风和日丽游春在泗水之滨，无边无际的风光焕然一新。\n谁都可以看出春天的面貌，春风吹得百花开放、万紫千红，到处都是春天的景致。\n\n","zhushi":"春日：春天。\n胜日：天气晴朗的好日子，也可看出人的好心情。\n寻芳：游春，踏青。\n泗水：河名，在山东省。\n滨：水边，河边。\n光景：风光风景。\n等闲：平常、轻易。“等闲识得”是容易识别的意思。\n东风：春风。\n\n"},{"id":"k65","title":"观书有感","author":"朱熹","dynasty":"宋","paragraphs":["半亩方塘一鉴开，天光云影共徘徊。","问渠那得清如许？为有源头活水来。(那 通：哪)"],"content_text":"半亩方塘一鉴开，天光云影共徘徊。问渠那得清如许？为有源头活水来。(那 通：哪)","pinyin":[["bàn","mǔ","fāng","táng","yī","jiàn","kāi","，","tiān","guāng","yún","yǐng","gòng","pái","huái","。"],["wèn","qú","nà","dé","qīng","rú","xǔ","？","wèi","yǒu","yuán","tóu","huó","shuǐ","lái","。","(","nà"," ","tōng","：","nǎ",")"]],"shiyi":"半亩大的方形池塘像一面镜子一样打开，清澈明净，天光、云影在水面上闪耀浮动。\n要问池塘里的水为何这样清澈呢？是因为有永不枯竭的源头源源不断地为它输送活水。\n\n","zhushi":"方塘：又称半亩塘，在福建尤溪城南郑义斋馆舍（后为南溪书院）内。朱熹父亲朱松与郑交好，故尝有《蝶恋花·醉宿郑氏别墅》词云：“清晓方塘开一境。落絮如飞，肯向春风定。”\n鉴：一说为古代用来盛水或冰的青铜大盆。镜子；也有学者认为镜子。指像鉴（镜子）一样可以照人。\n“天光”句：是说天的光和云的影子反映在塘水之中，不停地变动，犹如人在徘徊。\n徘徊：来回移动。\n为：因为。\n渠：它，第三人称代词，这里指方塘之水。\n那得：怎么会。\n那：怎么的意思。\n清如许：这样清澈。\n如：如此，这样。\n清：清澈。\n源头活水：比喻知识是不断更新和发展的，从而不断积累，只有在人生的学习中不断地学习、运用和探索，才能使自己永保先进和活力，就像水源头一样。\n\n"},{"id":"k66","title":"题临安邸","author":"林升","dynasty":"宋","paragraphs":["山外青山楼外楼，西湖歌舞几时休？","暖风熏得游人醉，直把杭州作汴州。"],"content_text":"山外青山楼外楼，西湖歌舞几时休？暖风熏得游人醉，直把杭州作汴州。","pinyin":[["shān","wài","qīng","shān","lóu","wài","lóu","，","xī","hú","gē","wǔ","jǐ","shí","xiū","？"],["nuǎn","fēng","xūn","dé","yóu","rén","zuì","，","zhí","bǎ","háng","zhōu","zuò","biàn","zhōu","。"]],"shiyi":"韵译\n青山无尽楼阁连绵望不见头，西湖上的歌舞几时才能停休？\n暖洋洋的香风吹得贵人如醉，简直是把杭州当成了那汴州。\n散译\n远处青山叠翠，近处楼台重重，西湖的歌舞何时才会停止？\n淫靡的香风陶醉了享乐的贵人们，简直是把偏安的杭州当作昔日的汴京！\n\n","zhushi":"临安：现在浙江杭州市，金人攻陷北宋首都汴京后，南宋统治者逃亡到南方，建都于临安。邸（dǐ）：旅店。\n西湖：杭州的著名风景区。几时休：什么时候休止。\n熏（xūn）：吹，用于温暖馥郁的风。\n直：简直。汴州：即汴京，今河南开封市。\n\n"},{"id":"k67","title":"游园不值","author":"叶绍翁","dynasty":"宋","paragraphs":["应怜屐齿印苍苔，小扣柴扉久不开。","春色满园关不住，一枝红杏出墙来。"],"content_text":"应怜屐齿印苍苔，小扣柴扉久不开。春色满园关不住，一枝红杏出墙来。","pinyin":[["yìng","lián","jī","chǐ","yìn","cāng","tái","，","xiǎo","kòu","chái","fēi","jiǔ","bù","kāi","。"],["chūn","sè","mǎn","yuán","guān","bù","zhù","，","yī","zhī","hóng","xìng","chū","qiáng","lái","。"]],"shiyi":"也许是园主担心我的木屐踩坏他那爱惜的青苔，轻轻地敲柴门，久久没有人来开。\n可是这满园的春色毕竟是关不住的，你看，那儿有一枝粉红色的杏花伸出墙头来。\n\n","zhushi":"游园不值：想游园没能进门儿。值，遇到；不值，没得到机会。\n应怜：概是感到心疼吧。应，表示猜测；怜，怜惜。屐（jī）齿：屐是木鞋，鞋底前后都有高跟儿，叫屐齿。\n小扣：轻轻地敲门。柴扉（fēi）：用木柴、树枝编成的门。\n\n"},{"id":"k68","title":"乡村四月","author":"翁卷","dynasty":"宋","paragraphs":["绿遍山原白满川，子规声里雨如烟。","乡村四月闲人少，才了蚕桑又插田。"],"content_text":"绿遍山原白满川，子规声里雨如烟。乡村四月闲人少，才了蚕桑又插田。","pinyin":[["lǜ","biàn","shān","yuán","bái","mǎn","chuān","，","zǐ","guī","shēng","lǐ","yǔ","rú","yān","。"],["xiāng","cūn","sì","yuè","xián","rén","shǎo","，","cái","liǎo","cán","sāng","yòu","chā","tián","。"]],"shiyi":"山坡田野间草木茂盛，稻田里的水色与天光相辉映。天空中烟雨蒙蒙，杜鹃声声啼叫，大地一片欣欣向荣的景象。\n四月到了，没有人闲着，刚刚结束了蚕桑的事又要插秧了。\n\n","zhushi":"山原：山陵和原野。白满川：指稻田里的水色映着天光。川：平地。\n子规：鸟名，杜鹃鸟。\n才了：刚刚结束。蚕桑：种桑养蚕。插田：插秧。\n\n"},{"id":"k69","title":"墨梅","author":"王冕","dynasty":"元","paragraphs":["吾家洗砚池头树，个个花开淡墨痕。","不要人夸好颜色，只流清气满乾坤。(版本一)"],"content_text":"吾家洗砚池头树，个个花开淡墨痕。不要人夸好颜色，只流清气满乾坤。(版本一)","pinyin":[["wú","jiā","xǐ","yàn","chí","tóu","shù","，","gè","gè","huā","kāi","dàn","mò","hén","。"],["bù","yào","rén","kuā","hǎo","yán","sè","，","zhī","liú","qīng","qì","mǎn","qián","kūn","。","(","bǎn","běn","yī",")"]],"shiyi":"我家洗砚池边有一棵梅树，朵朵开放的梅花都显出淡淡的墨痕。\n不需要别人夸它的颜色好看，只需要梅花的清香之气弥漫在天地之间。\n\n","zhushi":"墨梅：用墨笔勾勒出来的梅花。\n吾家：我家。因王羲之与王冕同姓，所以王冕便认为王姓自是一家。\n洗砚池：写字、画画后洗笔洗砚的池子。王羲之有“临池学书，池水尽黑”的传说。这里化用这个典故。\n池头：池边。头 ：边上。\n淡墨：水墨画中将墨色分为四种，如，清墨、淡墨、浓墨、焦墨。这里是说那朵朵盛开的梅花，是用淡淡的墨迹点化成的。\n痕：痕迹。\n清气:梅花的清香之气。\n满乾坤：弥漫在天地间。满：弥漫。乾坤：天地间。\n\n"},{"id":"k70","title":"石灰吟","author":"于谦","dynasty":"明","paragraphs":["千锤万凿出深山，烈火焚烧若等闲。","粉骨碎身全不怕，要留清白在人间。"],"content_text":"千锤万凿出深山，烈火焚烧若等闲。粉骨碎身全不怕，要留清白在人间。","pinyin":[["qiān","chuí","wàn","záo","chū","shēn","shān","，","liè","huǒ","fén","shāo","ruò","děng","xián","。"],["fěn","gǔ","suì","shēn","quán","bù","pà","，","yào","liú","qīng","bái","zài","rén","jiān","。"]],"shiyi":"（石灰石）只有经过千万次锤打才能从深山里开采出来，它把熊熊烈火的焚烧当作很平常的一件事。\n即使粉身碎骨也毫不惧怕，甘愿把一身清白留在人世间。\n\n","zhushi":"石灰吟：赞颂石灰。吟：吟颂。指古代诗歌体裁的一种名称（古代诗歌的一种形式）。\n千锤万凿：无数次的锤击开凿，形容开采石灰非常艰难。千、万：虚词，形容很多。锤：锤打。凿：开凿。\n若等闲：好像很平常的事情。若：好像、好似；等闲：平常，轻松。\n浑：全。\n清白：指石灰洁白的本色，又比喻高尚的节操。人间：人世间。\n\n"},{"id":"k71","title":"竹石","author":"郑燮","dynasty":"清","paragraphs":["咬定青山不放松，立根原在破岩中。","千磨万击还坚劲，任尔东西南北风。(坚'劲', 一作：韧)"],"content_text":"咬定青山不放松，立根原在破岩中。千磨万击还坚劲，任尔东西南北风。(坚'劲', 一作：韧)","pinyin":[["yǎo","dìng","qīng","shān","bù","fàng","sōng","，","lì","gēn","yuán","zài","pò","yán","zhōng","。"],["qiān","mó","wàn","jī","hái","jiān","jìn","，","rèn","ěr","dōng","xī","nán","běi","fēng","。","(","jiān","'","jìn","'",","," ","yī","zuò","：","rèn",")"]],"shiyi":"竹子抓住青山一点也不放松，它的根牢牢地扎在岩石缝中。\n经历成千上万次的折磨和打击，它依然那么坚强，不管是酷暑的东南风，还是严冬的西北风，它都能经受得住，还会依然坚韧挺拔。\n\n","zhushi":"竹石：扎根在石缝中的竹子。诗人是著名画家，他画的竹子特别有名，这是他题写在竹石画上的一首诗。\n咬定：比喻根扎得结实，像咬着青山不松口一样。\n立根：扎根，生根。\n原：本来,原本，原来。\n破岩：裂开的山岩，即岩石的缝隙。\n磨：折磨，挫折，磨炼。\n击：打击。\n坚劲：坚强有力。\n任：任凭，无论，不管。\n尔：你。\n\n"},{"id":"k72","title":"所见","author":"袁枚","dynasty":"清","paragraphs":["牧童骑黄牛，歌声振林樾。","意欲捕鸣蝉，忽然闭口立。"],"content_text":"牧童骑黄牛，歌声振林樾。意欲捕鸣蝉，忽然闭口立。","pinyin":[["mù","tóng","qí","huáng","niú","，","gē","shēng","zhèn","lín","yuè","。"],["yì","yù","bǔ","míng","chán","，","hū","rán","bì","kǒu","lì","。"]],"shiyi":"牧童骑在黄牛背上，嘹亮的歌声在林中回荡。\n忽然想要捕捉树上鸣叫的知了，就马上停止唱歌，一声不响地站立在树旁。\n\n","zhushi":"牧童：指放牛的孩子。\n振：振荡；回荡。说明牧童的歌声嘹亮。\n林樾（yuè）：指道旁成阴的树。\n欲：想要。\n捕：捉。\n鸣：叫。\n立：站立。\n\n"},{"id":"k73","title":"村居","author":"高鼎","dynasty":"清","paragraphs":["草长莺飞二月天，拂堤杨柳醉春烟。","儿童散学归来早，忙趁东风放纸鸢。"],"content_text":"草长莺飞二月天，拂堤杨柳醉春烟。儿童散学归来早，忙趁东风放纸鸢。","pinyin":[["cǎo","cháng","yīng","fēi","èr","yuè","tiān","，","fú","dī","yáng","liǔ","zuì","chūn","yān","。"],["ér","tóng","sàn","xué","guī","lái","zǎo","，","máng","chèn","dōng","fēng","fàng","zhǐ","yuān","。"]],"shiyi":"农历二月，村子前后的青草已经渐渐发芽生长，黄莺飞来飞去。杨柳披着长长的绿枝条，随风摆动，好像在轻轻地抚摸着堤岸。在水泽和草木间蒸发的水汽，如同烟雾般凝集着。杨柳似乎都陶醉在这浓丽的景色中。\n村里的孩子们放了学急忙跑回家，趁着东风把风筝放上蓝天。\n\n","zhushi":"村居：在乡村里居住时见到的景象。\n杨柳拂堤：像杨柳一样抚摸堤岸。醉：迷醉，陶醉。春烟：春天水泽、草木间蒸发形成的烟雾般的水汽。\n散学：放学。\n纸鸢：泛指风筝，它是一种纸做的形状像老鹰的风筝。鸢：老鹰。\n\n"},{"id":"k74","title":"己亥杂诗","author":"龚自珍","dynasty":"清","paragraphs":["九州生气恃风雷，万马齐喑究可哀。","我劝天公重抖擞，不拘一格降人才。"],"content_text":"九州生气恃风雷，万马齐喑究可哀。我劝天公重抖擞，不拘一格降人才。","pinyin":[["jiǔ","zhōu","shēng","qì","shì","fēng","léi","，","wàn","mǎ","qí","yīn","jiū","kě","āi","。"],["wǒ","quàn","tiān","gōng","zhòng","dǒu","sǒu","，","bù","jū","yī","gé","jiàng","rén","cái","。"]],"shiyi":"只有狂雷炸响般的巨大力量才能使中国大地发出勃勃生机，然而社会政局毫无生气终究是一种悲哀。\n我奉劝上天要重新振作精神，不要拘泥一定规格以降下更多的人才。\n\n","zhushi":"九州：中国的别称之一。分别是：冀州、兖州、青州、徐州、扬州、荆州、梁州、雍州和豫州。王昌龄《放歌行》：“清乐动千门，皇风被九州”。生气：生气勃勃的局面。恃（shì）：依靠。\n万马齐喑：比喻社会政局毫无生气。喑（yīn），沉默，不说话。\n天公：造物主。抖擞：振作，奋发。\n降：降生，降临。\n\n"}];
